-- Owner-authorized 6-paper TCF Reading v5 publication.
-- INSERT-only immutable paper content + exact six publication-pointer changes.
-- All historical versions and attempts remain untouched.
begin;
do $pre$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Expected 20 live reading tests'; end if;
 if not exists(select 1 from academy_tcf_reading.published_papers where test_id='tcf-reading-01' and version='tcf-reading-2026-11-editorial-v4') then raise exception 'Reading Test 1 unexpected live version; abort'; end if;
 if not exists(select 1 from academy_tcf_reading.published_papers where test_id='tcf-reading-02' and version='tcf-reading-2026-11-reference-v3') then raise exception 'Reading Test 2 unexpected live version; abort'; end if;
 if not exists(select 1 from academy_tcf_reading.published_papers where test_id='tcf-reading-03' and version='tcf-reading-2026-11-reference-v3') then raise exception 'Reading Test 3 unexpected live version; abort'; end if;
 if not exists(select 1 from academy_tcf_reading.published_papers where test_id='tcf-reading-04' and version='tcf-reading-2026-11-reference-v3') then raise exception 'Reading Test 4 unexpected live version; abort'; end if;
 if not exists(select 1 from academy_tcf_reading.published_papers where test_id='tcf-reading-05' and version='tcf-reading-2026-11-editorial-v4') then raise exception 'Reading Test 5 unexpected live version; abort'; end if;
 if not exists(select 1 from academy_tcf_reading.published_papers where test_id='tcf-reading-06' and version='tcf-reading-2026-11-reference-v3') then raise exception 'Reading Test 6 unexpected live version; abort'; end if;
 if exists(select 1 from academy_tcf_reading.published_papers
  where test_id not in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06')
    and version<>'tcf-reading-2026-11-reference-v3') then
   raise exception 'Unexpected remaining tests version; abort';
 end if;
 if exists(select 1 from academy_tcf_reading.papers where version='tcf-reading-2026-11-advanced-v5' and id in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06')) then
   raise exception 'v5 paper version already exists; never overwrite immutable papers';
 end if;
end $pre$;
insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-01','tcf-reading-2026-11-advanced-v5',$paper${"id":"tcf-reading-01","version":"tcf-reading-2026-11-advanced-v5","title":"TCF Reading · Test 01","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Information à tous les voyageurs : En raison de fortes chutes de neige, tous les vols à destination de Genève sont annulés ce lundi. Les passagers concernés peuvent modifier leur billet sans frais. Aéroport International de Lyon","question":"Que doivent faire les passagers concernés par cette annonce ?","options":["Demander un nouveau trajet sans frais","Modifier la destination en payant un supplément","Se présenter pour un vol à l'heure prévue","Attendre une reprise des vols pour Genève"],"correct":"A","explanation":"« Les passagers concernés peuvent modifier leur billet sans frais » : le changement de vol est gratuit."},{"number":2,"points":3,"passage":"Message de la bibliothèque : Le retour des livres empruntés est prolongé jusqu’au 10 janvier, sans pénalité. Vous pouvez également utiliser la boîte extérieure prévue à cet effet. Bibliothèque municipale","question":"Que propose la bibliothèque à ses usagers ?","options":["Rendre les emprunts sans pénalité avant le 10 janvier","Déposer uniquement les livres le 10 janvier","Renouveler tous les prêts pour un mois","Retirer les livres à la bibliothèque après la date"],"correct":"A","explanation":"Le retour est prolongé « jusqu’au 10 janvier, sans pénalité ». Aucune prolongation sans limite n’est annoncée."},{"number":3,"points":3,"passage":"Cher(e)s client(e)s, Notre boutique en ligne sera en maintenance le jeudi 7 mars de 1 h à 5 h du matin. Pendant cette période, aucune commande ne pourra être passée. L’équipe de Maison Bio","question":"Que se passera-t-il entre 1 h et 5 h du matin le 7 mars ?","options":["Les commandes seront enregistrées avec retard","Les commandes seront possibles uniquement par téléphone","Les commandes ne pourront être modifiées qu'après cinq heures","Les commandes en ligne seront suspendues pendant la maintenance"],"correct":"D","explanation":"La maintenance a lieu de 1 h à 5 h ; « aucune commande ne pourra être passée » pendant cette période."},{"number":4,"points":3,"passage":"Annonce à tous les parents : L’école organise une sortie au musée pour les élèves de CE2 le mardi 17 avril. Les enfants doivent apporter un pique-nique, une bouteille d’eau et porter des chaussures confortables. École Les Érables","question":"Quel est l’objectif de ce message ?","options":["Demander aux parents de réserver les billets","Inviter les élèves à choisir leur musée préféré","Préciser le matériel nécessaire pour une sortie scolaire","Annoncer une réunion préparatoire à la sortie"],"correct":"C","explanation":"Le message précise la date de la sortie et ce que les enfants doivent apporter et porter."},{"number":5,"points":9,"passage":"Chers voisins, La fête de quartier annuelle aura lieu le samedi 15 juillet à partir de 16 h dans le parc du square des Lilas. Apportez un plat à partager et votre bonne humeur ! Jeux pour enfants, musique et tombola sont prévus. Le comité de quartier","question":"Pourquoi les voisins sont-ils invités au parc ?","options":["Participer à un repas associatif réservé aux enfants","Se réunir pour préparer la prochaine tombola","Faire connaissance pendant une fête de quartier","Se retrouver pour organiser un nettoyage du parc"],"correct":"C","explanation":"La fête de quartier prévoit un repas partagé, des jeux, de la musique et une tombola : il s’agit d’une célébration locale."},{"number":6,"points":9,"passage":"Annonce : Appartement 2 pièces à louer à partir du 1er septembre. 650 €/mois, charges comprises. Situé au 2e étage avec balcon, à 5 minutes du métro. Idéal pour une personne seule ou un jeune couple. Contact : immo.dubois@email.fr","question":"Quel type de logement est proposé ?","options":["Un appartement de deux pièces pour une ou deux personnes","Un studio à louer avec un espace extérieur","Un logement partagé entre plusieurs colocataires","Un appartement réservé aux familles nombreuses"],"correct":"A","explanation":"L’annonce indique un appartement de deux pièces, « idéal pour une personne seule ou un jeune couple »."},{"number":7,"points":9,"passage":"Bonjour ! Je viens d’avoir une excellente nouvelle : ma sœur attend un bébé ! Toute la famille est ravie, et je suis tellement impatiente de devenir tata ! On organise un petit repas dimanche prochain pour célébrer cette belle annonce. Tu veux venir ? Élodie","question":"Pourquoi Élodie est-elle heureuse ?","options":["Sa sœur prépare une fête d'anniversaire","Elle vient d'avoir un enfant","Elle retrouve sa sœur après un voyage","Elle va bientôt devenir tante"],"correct":"D","explanation":"Élodie annonce que sa sœur « attend un bébé » et qu’elle est impatiente de devenir tante."},{"number":8,"points":9,"passage":"Offre d’emploi – Assistant(e) administratif(ve) Entreprise locale recherche un(e) assistant(e) à mi-temps pour assurer l’accueil, la gestion des appels et le traitement des courriels. Expérience souhaitée, maîtrise de Word et Excel exigée. Envoyer CV à : emploi@bureauplus.fr","question":"Quel profil l’entreprise cherche-t-elle ?","options":["Une personne chargée uniquement des appels","Un responsable de recrutement à temps plein","Un spécialiste de la communication numérique","Un assistant administratif à l'aise avec la bureautique"],"correct":"D","explanation":"Le poste d’assistant administratif exige la maîtrise de Word et Excel, des outils bureautiques."},{"number":9,"points":9,"passage":"Invitation spéciale : Participez à notre soirée de réseautage pour les jeunes professionnels, jeudi 12 octobre à 18 h, au café Connect. Venez rencontrer des entrepreneurs, échanger des idées et élargir votre réseau. Entrée gratuite avec inscription en ligne.","question":"Quel est l’objectif principal de cet événement ?","options":["Obtenir un entretien d'embauche auprès des invités","Présenter un programme de formation diplômante","Faire des rencontres dans un cadre professionnel","Réserver un espace de travail au café"],"correct":"C","explanation":"La soirée permet de « rencontrer des entrepreneurs » et d’« élargir votre réseau »."},{"number":10,"points":9,"passage":"Chers amis, Cette année encore, nous organisons une collecte pour aider les familles en difficulté avant la rentrée. Vous pouvez déposer fournitures scolaires et vêtements en bon état à la mairie avant le 25 août. Merci pour votre générosité ! Association Entraide locale","question":"Quel est le but de cette collecte ?","options":["Aider les familles à préparer la rentrée scolaire","Collecter des dons pour un voyage des élèves","Financer une activité de loisirs à l'école","Réunir les familles pour une fête de quartier"],"correct":"A","explanation":"La collecte de fournitures et de vêtements aide les familles en difficulté « avant la rentrée »."},{"number":11,"points":15,"passage":"Cher Antoine, Je t’écris depuis le petit village de Kpalimé, au Togo, où je participe à un programme de volontariat depuis deux semaines. Nos journées sont bien remplies : nous aidons les instituteurs dans une école primaire, et l’après-midi, nous organisons des ateliers de lecture et d’hygiène pour les enfants. La chaleur est intense, mais l’ambiance est incroyable ! Je loge chez une famille locale très accueillante, et j’ai déjà goûté des plats typiques comme le fufu et l’igname pilée. Je prends beaucoup de photos et je t’enverrai un album à mon retour. À bientôt, Camille","question":"Pourquoi Camille est-elle au Togo ?","options":["Pour suivre une formation à l'université","Pour préparer un séjour touristique dans le pays","Pour participer bénévolement à un projet scolaire","Pour mener une enquête sur les entreprises locales"],"correct":"C","explanation":"Camille participe à un volontariat dans une école et organise des ateliers de lecture et d’hygiène."},{"number":12,"points":15,"passage":"Info aux parents : Nous vous informons qu’un mouvement de grève touchera l’ensemble des écoles primaires de la ville le jeudi 14 décembre. Il n’y aura ni cours, ni accueil périscolaire, ni cantine ce jour-là. Merci de prendre vos dispositions. Un service minimum d’accueil sera assuré à l’école Voltaire pour les enfants dont les deux parents travaillent et qui n’ont aucune solution de garde. Direction des affaires scolaires","question":"Quelle conséquence aura cette grève pour les familles ?","options":["Certains enfants suivront les cours dans une autre école","Les repas seront maintenus malgré l'arrêt des cours","Tous les élèves pourront être accueillis normalement","Des solutions d'accueil limitées seront prévues sous conditions"],"correct":"D","explanation":"Les cours et les services habituels sont supprimés. Seuls les enfants répondant aux conditions indiquées peuvent bénéficier de l’accueil à l’école Voltaire."},{"number":13,"points":15,"passage":"Technologie – Transports Depuis quelques semaines, des navettes électriques sans conducteur circulent dans certains quartiers de Lyon. Ces véhicules autonomes peuvent transporter jusqu’à 10 personnes et s’arrêtent à la demande, grâce à une application mobile. Ils roulent à faible vitesse, ce qui les rend très sûrs, notamment dans les zones piétonnes. Ce projet pilote est mené en partenariat avec la métropole de Lyon pour tester de nouvelles solutions de mobilité plus écologiques. Des questionnaires sont proposés aux passagers à la fin de chaque trajet pour recueillir leur avis sur le confort et la fiabilité du service.","question":"Que teste la ville de Lyon avec ce projet ?","options":["Une nouvelle ligne de métro souterraine","Des bus électriques avec chauffeur","Des navettes autonomes écologiques","Des vélos électriques à partager"],"correct":"C","explanation":"Les navettes sont électriques, « sans conducteur » et testées comme solution de mobilité écologique."},{"number":14,"points":15,"passage":"Cher Louis, Tu ne devineras jamais où je suis ! J’étais censée passer le week-end à Nantes, mais mon train a été annulé à cause d’un problème sur la ligne. J’ai donc pris un bus pour rejoindre une amie à La Rochelle, et nous avons décidé de passer deux jours ici. C’est une très belle ville ! On s’est promenées sur le port, et on a même visité l’aquarium. On profite du soleil et de l’air marin. Finalement, ce changement de programme était une bonne surprise. Je repars mardi matin. À très vite, Inès","question":"Dans quelle ville Inès a-t-elle passé le week-end ?","options":["À La Rochelle","À Nantes","À Paris","À Bordeaux"],"correct":"A","explanation":"Le train pour Nantes ayant été annulé, Inès a rejoint une amie à La Rochelle et y a passé deux jours."},{"number":15,"points":15,"passage":"Écologie – Actualité Le gouvernement a annoncé la mise en place progressive d’une interdiction des emballages plastiques à usage unique dans les commerces de proximité. Dès janvier prochain, les sacs plastiques seront bannis des boulangeries, des boucheries et des primeurs. Les clients devront venir avec leurs propres contenants, ou utiliser des sacs réutilisables en tissu ou en papier. Cette décision vise à réduire considérablement la production de déchets non recyclables, alors que la pollution plastique continue d’augmenter dans les milieux naturels. Des campagnes d'information sont prévues pour accompagner les professionnels et les consommateurs dans cette transition.","question":"Quel est l’objectif principal de cette mesure ?","options":["Favoriser la consommation locale","Réduire l’utilisation du plastique jetable","Protéger les commerces indépendants","Améliorer l’hygiène des produits vendus"],"correct":"B","explanation":"L’interdiction vise à « réduire considérablement la production de déchets non recyclables » liés aux plastiques à usage unique."},{"number":16,"points":15,"passage":"Vie locale Ce samedi, la maison des associations accueille un forum sur le thème “Grandir à l’ère numérique”. Parents, enseignants, psychologues et spécialistes du numérique interviendront pour échanger sur l’impact des écrans dans la vie des enfants et des adolescents. Des ateliers sont aussi prévus pour les jeunes, afin de leur apprendre à reconnaître les fausses informations, à limiter leur temps d’écran, et à mieux gérer les réseaux sociaux. L’entrée est libre, mais les places sont limitées. Renseignements sur le site de la mairie.","question":"Quel est le thème principal de cet événement ?","options":["L’impact de la technologie sur la santé physique","Les méthodes pour améliorer la mémoire","L’éducation des jeunes au numérique","Le développement de logiciels éducatifs"],"correct":"C","explanation":"Le forum « Grandir à l’ère numérique » porte sur les écrans, les fausses informations et les réseaux sociaux chez les jeunes."},{"number":17,"points":15,"passage":"Message d’Aurélie à son frère : Devine quoi ! J’ai enfin quitté mon travail au bureau pour me lancer dans ma passion : la pâtisserie. Je me suis inscrite à une formation intensive de six mois à Lyon pour apprendre les bases. Je me lève tôt, je finis tard, mais je n’ai jamais été aussi heureuse. Mon objectif est d’ouvrir ma propre boutique d’ici un an. Je commence à créer mes premières recettes, et mes collègues de cours sont super motivants. Tu peux venir goûter mes créations quand tu veux !","question":"Qu’a décidé de faire Aurélie ?","options":["Créer une école de cuisine","Faire une reconversion professionnelle","Ouvrir une boulangerie traditionnelle","Déménager à l’étranger"],"correct":"B","explanation":"Aurélie a quitté son emploi de bureau pour se former à la pâtisserie : elle change de métier."},{"number":18,"points":15,"passage":"Avis aux usagers du réseau TER À partir du 15 avril, le train de 7 h 22 entre Grenoble et Chambéry sera supprimé en raison de travaux sur la voie. Les voyageurs sont invités à prendre le train de 7 h 55, ou à utiliser les cars de substitution mis en place. Des retards sont également à prévoir sur les lignes voisines pendant la durée des travaux. Des annonces seront faites en gare, et les informations seront mises à jour chaque jour sur le site TER.","question":"Qu’indique cet avis aux voyageurs ?","options":["La suppression d’un train du matin","Un changement de gare de départ","L’ajout d’un nouveau train en matinée","La gratuité des trains pendant les travaux"],"correct":"A","explanation":"L’avis annonce que « le train de 7 h 22 […] sera supprimé » à partir du 15 avril."},{"number":19,"points":15,"passage":"Société – Médias Selon une étude récente, près de 40 % des adultes de moins de 30 ans s’informent exclusivement via les réseaux sociaux. Ce phénomène inquiète certains experts, car ces plateformes mélangent contenus d’information, opinions personnelles, publicités, et fausses nouvelles. De plus, les algorithmes montrent souvent aux utilisateurs les contenus qui renforcent leurs idées déjà existantes, ce qui limite l’ouverture d’esprit. Des associations proposent désormais des ateliers d’éducation aux médias, notamment dans les lycées et les universités.","question":"Quel problème est soulevé dans cet article ?","options":["Le manque de connexion dans les zones rurales","Le coût croissant des abonnements presse","L’augmentation du temps passé à lire les journaux papier","Les dangers d’une information non vérifiée en ligne"],"correct":"D","explanation":"Le texte évoque le mélange d’informations, d’opinions, de publicités et de fausses nouvelles sur les réseaux sociaux."},{"number":20,"points":21,"passage":"La municipalité de Saint-Alban a lancé un programme incitatif pour encourager les habitants à installer des panneaux solaires sur leurs toits. Toute personne qui s’inscrit avant le 30 septembre bénéficiera d’une subvention couvrant jusqu’à 40 % des frais d’installation. En plus de l’aide financière, des ateliers d’information sont organisés pour expliquer les avantages environnementaux et économiques de cette transition. Le maire espère ainsi faire de Saint-Alban un exemple en matière d’énergie renouvelable. Il espère aussi réduire à terme les factures d’électricité de la population locale et contribuer aux objectifs nationaux de réduction carbone.","question":"Quelle est l’intention principale de la municipalité ?","options":["Promouvoir une réduction de la consommation d’électricité","Accroître l’usage des énergies fossiles","Réduire le nombre de toitures anciennes","Encourager les résidents à adopter l’énergie solaire"],"correct":"D","explanation":"Le programme subventionne l’installation de panneaux solaires afin d’encourager l’énergie renouvelable."},{"number":21,"points":21,"passage":"Dans une petite ville du sud de la France, une école a décidé de remplacer tous les manuels papier par des tablettes numériques. L’objectif est de moderniser les méthodes d’enseignement tout en réduisant le poids des cartables. Certains parents s’inquiètent de l’exposition prolongée des enfants aux écrans, mais les enseignants affirment que les contenus numériques permettent une approche plus interactive et personnalisée de l’apprentissage. Un suivi statistique des résultats sera aussi mis en place pour évaluer l’impact réel sur les performances scolaires.","question":"Quel est le principal changement apporté à cette école ?","options":["La suppression des devoirs à domicile","La réduction du nombre d’élèves par classe","L’introduction de tablettes pour remplacer les livres","La mise en place d’activités sportives"],"correct":"C","explanation":"L’école « a décidé de remplacer tous les manuels papier par des tablettes numériques »."},{"number":22,"points":21,"passage":"La Bibliothèque Nationale a récemment lancé une campagne de collecte de livres rares auprès du public. L’idée est de constituer un fonds de documents historiques afin de préserver la mémoire culturelle. Les particuliers peuvent proposer des ouvrages anciens, qui seront ensuite évalués par une équipe de spécialistes. En échange, leur nom sera mentionné dans les archives numériques et ils recevront un certificat de contribution. L’initiative a déjà permis de rassembler plus de 800 ouvrages datant d’avant 1900.","question":"Quel est le but de cette campagne ?","options":["Enrichir les collections personnelles des donateurs","Créer un musée de livres contemporains","Revendre les livres rares à des collectionneurs privés","Préserver des livres historiques pour les générations futures"],"correct":"D","explanation":"La collecte constitue un fonds de documents historiques pour « préserver la mémoire culturelle »."},{"number":23,"points":21,"passage":"Le chef étoilé Alain Morel a décidé d’ouvrir un restaurant gastronomique 100 % végétarien, une première pour lui. Cette décision s’inscrit dans une volonté de proposer une cuisine durable sans sacrifier le goût. Dans ses plats, il utilise des légumes oubliés, des légumineuses locales et des épices rares. Le restaurant connaît un succès inattendu, attirant même des amateurs de viande curieux de cette nouvelle expérience culinaire. Il envisage déjà d’ouvrir une deuxième adresse dans une autre grande ville européenne.","question":"Quelle orientation a pris le chef Alain Morel ?","options":["Il a arrêté la cuisine pour se consacrer à l’agriculture","Il propose une cuisine végétarienne de haute qualité","Il a ouvert une école de cuisine spécialisée en viande","Il se consacre uniquement à la pâtisserie"],"correct":"B","explanation":"Le chef ouvre un restaurant gastronomique « 100 % végétarien » sans sacrifier le goût."},{"number":24,"points":21,"passage":"Depuis plusieurs années, la ville de Rouen est confrontée à une augmentation du nombre de vélos dans les rues, ce qui provoque parfois des conflits entre cyclistes et piétons. Pour remédier à cela, la mairie a décidé d’élargir certaines voies piétonnes et d’installer des pistes cyclables séparées. Une campagne de sensibilisation a également été lancée pour rappeler à chacun les règles de bonne conduite en ville. Les premières évaluations montrent déjà une baisse des incidents signalés.","question":"Quelle mesure la ville a-t-elle prise pour réduire les conflits ?","options":["Interdire les vélos dans le centre-ville","Séparer les pistes pour piétons et cyclistes","Créer des zones de circulation exclusivement piétonnes","Limiter le nombre de vélos autorisés"],"correct":"B","explanation":"La mairie installe « des pistes cyclables séparées » et élargit certaines voies piétonnes."},{"number":25,"points":21,"passage":"Une étude menée par l’Institut de Santé Publique montre que près d’un tiers des Français dorment moins de six heures par nuit. Ce manque de sommeil chronique a des répercussions importantes sur la concentration, la mémoire et le moral. Les chercheurs recommandent d’adopter une routine régulière, de limiter les écrans en soirée et d’éviter les boissons stimulantes après 17h. D’après eux, un sommeil réparateur devrait durer au moins sept heures pour les adultes.","question":"Quel effet du manque de sommeil ressort de l'étude ?","options":["Le manque de sommeil affecte d'abord les capacités mentales, le moral étant lié aux habitudes du soir","Les effets du manque de repos se manifestent surtout après consommation de stimulants","Une durée de sommeil insuffisante peut perturber la mémoire et l'état émotionnel","Les conseils donnés visent la concentration plutôt que les conséquences sur l'humeur"],"correct":"C","explanation":"L'étude relie un sommeil insuffisant à la concentration, à la mémoire et au moral. Les conseils sur les écrans et boissons sont des recommandations de prévention, pas une cause unique démontrée."},{"number":26,"points":21,"passage":"Clémence a toujours rêvé d’écrire un roman. Après avoir suivi un atelier d’écriture en ligne pendant six mois, elle a terminé son premier manuscrit. Encouragée par les retours positifs de ses pairs, elle a décidé de l’envoyer à plusieurs maisons d’édition. Quelques semaines plus tard, elle a reçu une proposition de contrat pour publication. Son livre paraîtra dans quelques mois, et elle espère qu’il trouvera son public. Elle envisage même de commencer un second tome.","question":"Quelle évolution du projet de Clémence résume le texte ?","options":["Son premier manuscrit donne lieu à un accord de publication après plusieurs démarches","Les retours positifs du public entraînent la signature d'un contrat d'édition","Le projet de second tome est annoncé avant l'envoi du premier manuscrit","L'atelier permet de publier un roman sans échange avec une maison d'édition"],"correct":"A","explanation":"Clémence suit un atelier, termine un manuscrit, sollicite des maisons d'édition et obtient un contrat. Le texte raconte l'aboutissement d'un projet personnel, pas le fonctionnement de l'atelier."},{"number":27,"points":21,"passage":"Le Mont-Blanc, plus haut sommet d’Europe occidentale, attire chaque été des milliers d’alpinistes amateurs. Face à la hausse du nombre d’accidents, les autorités locales ont mis en place un système de réservation obligatoire et des contrôles renforcés de l’équipement. Cette initiative vise à responsabiliser les randonneurs et à préserver l’environnement fragile de la montagne. Un guide de bonnes pratiques a aussi été distribué aux visiteurs avant l’ascension.","question":"Quel objectif commun relie les nouvelles mesures ?","options":["Répartir les visiteurs entre itinéraires en conservant les mêmes pratiques d'ascension","Réduire l'accidentologie principalement grâce à une meilleure information touristique","Rendre la montagne plus accessible en adaptant les contrôles aux profils des visiteurs","Prévenir les accidents tout en réduisant l'impact des ascensions sur le milieu"],"correct":"D","explanation":"Réservation et contrôle des équipements répondent à la hausse des accidents, tandis que les bonnes pratiques visent aussi le milieu fragile. Les mesures poursuivent ces deux objectifs."},{"number":28,"points":21,"passage":"Chaque année, la ville de Nantes organise une « nuit des musées » durant laquelle tous les musées ouvrent gratuitement leurs portes de 18h à minuit. Des spectacles vivants, des visites guidées, et des ateliers interactifs sont proposés. L’événement attire aussi bien des familles que des touristes de passage, et vise à rendre la culture accessible à tous. L’an dernier, plus de 20 000 personnes y ont participé, un record pour la ville.","question":"Quelle finalité générale justifie le dispositif ?","options":["Développer la fréquentation régulière des musées parmi leurs visiteurs habituels","Favoriser l'accès d'un public varié à plusieurs formes d'expression culturelle","Mettre en avant les horaires nocturnes pour prolonger les visites touristiques","Répartir les visiteurs entre établissements pour maîtriser les entrées record"],"correct":"B","explanation":"L'ouverture gratuite et les ateliers visent à rendre la culture accessible à tous. La fréquentation importante est un résultat constaté, non le but formulé."},{"number":29,"points":21,"passage":"La pollution lumineuse est un phénomène de plus en plus étudié par les scientifiques. Dans certaines régions, l’éclairage nocturne excessif perturbe le cycle de sommeil des animaux et empêche l’observation astronomique. Plusieurs communes ont commencé à éteindre ou réduire l’intensité des lampadaires après 23h pour retrouver un ciel nocturne plus naturel. Cela permet aussi de réduire la consommation d’énergie et de faire des économies budgétaires.","question":"Quelle double perturbation le texte attribue-t-il à l'éclairage excessif ?","options":["La désorganisation des rythmes des animaux et la hausse des dépenses publiques","L'altération du repos de la faune et l'observation plus difficile des étoiles","La réduction des lampadaires et la baisse d'activité des animaux en ville","La dégradation du ciel nocturne et le raccourcissement du sommeil humain"],"correct":"B","explanation":"La lumière excessive perturbe le sommeil des animaux et gêne l'observation astronomique. Les économies d'énergie sont un effet recherché par la réduction de l'éclairage, pas un dommage provoqué."},{"number":30,"points":26,"passage":"Les océans couvrent plus de 70 % de la surface de la Terre et jouent un rôle essentiel dans la régulation du climat. Ils absorbent une grande partie du dioxyde de carbone émis par les activités humaines. Cependant, cette absorption entraîne l’acidification des eaux marines, ce qui menace les récifs coralliens et la biodiversité. Des scientifiques tirent la sonnette d’alarme depuis plusieurs années. Ils soulignent qu’il est urgent de réduire les émissions pour préserver les écosystèmes marins.","question":"Quel mécanisme rend le rôle climatique des océans ambivalent ?","options":["L'absorption marine réduit l'effet des émissions tout en accélérant la disparition du carbone dissous","Un même processus modère l'effet du CO₂ atmosphérique tout en modifiant défavorablement l'eau de mer","Les émissions favorisent l'absorption océanique, qui réduit ensuite l'acidité autour des récifs","Le stockage du carbone par les océans devient nuisible surtout lorsque les émissions diminuent"],"correct":"B","explanation":"B. Les océans atténuent une partie de l'accumulation atmosphérique du CO₂ mais l'absorption acidifie l'eau et menace certains écosystèmes. A déplace le mécanisme vers une disparition du carbone dissous, C inverse l'effet sur l'acidité et D attribue le risque à une baisse des émissions."},{"number":31,"points":26,"passage":"Dans une école expérimentale, les élèves n’ont pas d’horaires fixes ni de manuels imposés. Ils choisissent leurs sujets d’étude selon leurs intérêts. Les enseignants jouent le rôle de guides, les aidant à approfondir leurs recherches et à formuler leurs propres questions. Ce modèle éducatif attire l’attention de nombreux pédagogues en quête d’alternatives au système traditionnel. Les résultats des élèves à long terme sont en cours d’évaluation.","question":"Quelle réserve doit accompagner l'intérêt pour cette méthode ?","options":["Le manque de manuels imposés complique l'analyse des performances individuelles","L'attrait suscité par la méthode précède la validation de ses résultats dans la durée","Le rôle de guide des enseignants empêche d'attribuer les progrès aux élèves","L'absence d'horaires fixes rend les résultats immédiatement comparables"],"correct":"B","explanation":"B. Le dispositif intéresse des pédagogues, mais les effets sur les élèves à long terme sont encore étudiés. L'intérêt ne constitue pas une preuve d'efficacité."},{"number":32,"points":26,"passage":"La ville de Bordeaux a récemment transformé une ancienne voie ferrée en promenade urbaine verte. Cet espace, long de plusieurs kilomètres, est aujourd’hui planté d’arbres et de fleurs locales. Les habitants s’y promènent, y font du vélo et participent à des ateliers de jardinage. Ce projet, qui favorise la biodiversité et le bien-être, inspire d’autres villes européennes à lancer des initiatives similaires. Une enquête a montré une forte hausse de la satisfaction des résidents.","question":"Quelle conséquence générale de la reconversion est mise en avant ?","options":["Les espaces de loisirs ont augmenté sans modifier la vie écologique du quartier","Les nouveaux usages de la promenade accompagnent des bénéfices pour le vivant","L'ancienne infrastructure est réutilisée pour renforcer les transports locaux","L'intérêt d'autres villes constitue le principal effet de la reconversion"],"correct":"B","explanation":"La reconversion de la voie ferrée combine biodiversité, promenades, vélo, jardinage et satisfaction accrue des habitants. Le projet ne restaure pas l'usage ferroviaire."},{"number":33,"points":26,"passage":"<< Les Brumes du Nord >> est un roman d’aventure situé dans une Scandinavie imaginaire. L’intrigue repose sur une légende ancestrale, mais peine à captiver le lecteur. Les personnages manquent parfois de nuances, bien que certains passages soient bien écrits. Le style de l’auteur est fluide, mais certains critiques notent un manque de suspense. Malgré cela, le livre reste plaisant pour les amateurs de récits nordiques.","question":"Quel jugement porte principalement sur la conduite de l'intrigue ?","options":["Le récit conserve des qualités d'écriture sans maintenir suffisamment le suspense","Les personnages donnent une lecture nuancée d'une légende pourtant prévisible","La fluidité du style compense une intrigue dont le rythme s'accélère tardivement","L'univers nordique crée un cadre plaisant malgré des scènes d'action trop nombreuses"],"correct":"A","explanation":"A. Le texte reproche à l'intrigue de peu captiver et de manquer de suspense tout en saluant des passages bien écrits. Les autres réponses attribuent au texte des qualités ou défauts différents."},{"number":34,"points":26,"passage":"Une enquête sociologique récente révèle que les jeunes adultes privilégient aujourd’hui les expériences plutôt que les possessions matérielles. Voyager, assister à des concerts ou pratiquer une activité nouvelle sont perçus comme plus enrichissants que l’achat d’objets. Les réseaux sociaux renforcent cette tendance, en valorisant les récits personnels et les découvertes. Cette évolution soulève des questions sur les comportements économiques futurs et la définition du succès.","question":"Quel changement de critères de réussite l'enquête décrit-elle ?","options":["La valeur accordée aux expériences résulte d'une baisse des achats chez les jeunes","La réussite se mesure désormais principalement aux destinations visitées","Les expériences vécues comptent davantage que les biens possédés dans l'idée de réussite","La visibilité des voyages sur les réseaux fait reculer les activités nouvelles"],"correct":"C","explanation":"L'enquête valorise les expériences par rapport aux biens matériels et souligne le rôle des réseaux sociaux dans cette préférence. Elle ne conclut pas à l'abandon de la consommation."},{"number":35,"points":26,"passage":"Une équipe de chercheurs a étudié la relation entre la musique et la mémoire. Ils ont constaté que les personnes âgées se souvenaient mieux d’un événement si une chanson familière était associée au moment. Ce lien émotionnel semble renforcer les connexions neuronales. Des tests montrent que les malades d’Alzheimer réagissent plus positivement à la musique qu’à d’autres stimuli. Cette découverte ouvre la voie à de nouvelles thérapies non médicamenteuses.","question":"Quelle interprétation des résultats est la plus prudente ?","options":["Les réactions à la musique montrent que le traitement a déjà prouvé une efficacité clinique","Les émotions attachées à un air connu pourraient renforcer le rappel d'un souvenir","La familiarité d'une chanson explique pourquoi les patients se souviennent davantage de faits récents","L'étude établit que les effets sur la mémoire sont identiques pour tout type de stimulus"],"correct":"B","explanation":"B. Le lien affectif avec une chanson familière semble favoriser le souvenir; le passage ne démontre ni guérison, ni primauté des souvenirs récents, ni égalité des stimuli."},{"number":36,"points":33,"passage":"Les restaurants végétariens se multiplient dans les grandes villes européennes. Il y a quelques années, ce type d’établissement était encore marginal, fréquenté par une minorité de consommateurs engagés. Aujourd’hui, la situation a changé. De nombreuses personnes consomment moins de viande, parfois pour des raisons de santé, parfois pour des préoccupations environnementales ou éthiques. Les chefs s’adaptent à cette tendance et proposent des plats créatifs, riches en saveurs, capables de convaincre même les plus fervents amateurs de viande. Le succès de ces établissements repose aussi sur la qualité des produits utilisés : légumes bio, circuits courts, recettes de saison. Ce mouvement entraîne une revalorisation des légumes, longtemps considérés comme simples accompagnements. En rendant la cuisine végétale attrayante et gourmande, les restaurants végétariens participent à une véritable révolution culinaire. Ils attirent désormais une clientèle variée et fidèle.","question":"Quelle évolution de la cuisine végétarienne est soulignée ?","options":["La créativité des plats élargit l'attrait d'une cuisine centrée sur les légumes","Les établissements attirent surtout les consommateurs motivés par la santé","Les menus végétariens réussissent principalement grâce à leur faible coût","Les circuits courts remplacent progressivement les recettes élaborées"],"correct":"A","explanation":"Les chefs travaillent les légumes, leurs saveurs et leur provenance pour séduire un public plus large. Le texte décrit une transformation de l'image de la cuisine végétale."},{"number":37,"points":33,"passage":"Le télétravail, autrefois réservé à quelques secteurs très spécialisés, s’est largement démocratisé depuis la crise sanitaire. Beaucoup d’entreprises ont adopté un fonctionnement hybride, mêlant présence au bureau et travail à distance. Les salariés apprécient cette souplesse, qui leur permet de mieux concilier vie professionnelle et personnelle. Mais le télétravail n’est pas sans inconvénient : isolement social, difficulté à séparer vie privée et vie professionnelle, surcharge de travail… Les managers doivent repenser leurs méthodes de suivi et de communication pour maintenir la cohésion de leurs équipes. D’un autre côté, certaines entreprises y voient une opportunité de réduire leurs coûts immobiliers. Il est donc probable que ce mode d’organisation s’installe durablement. Cependant, il faudra encore du temps pour trouver un équilibre adapté à tous les types de métiers et de personnalités.","question":"Quel défi d'organisation collective accompagne la diffusion du télétravail ?","options":["Les salariés apprécient une souplesse utile à leur vie personnelle et familiale","Les entreprises envisagent aussi les économies permises sur leurs locaux","La pérennité du travail hybride exige des ajustements dans la vie des équipes","Les difficultés de séparation des espaces privés et professionnels persistent"],"correct":"C","explanation":"L'organisation hybride est appréciée mais impose des méthodes de suivi et de communication pour préserver la cohésion. Les bénéfices immobiliers ne sont qu'un aspect."},{"number":38,"points":33,"passage":"Dans certaines écoles de campagne, les enseignants doivent faire preuve d’une grande polyvalence. Il n’est pas rare qu’un seul professeur s’occupe de plusieurs niveaux dans une même salle de classe. Cela demande une organisation rigoureuse et beaucoup de créativité. Les élèves, bien que très jeunes, apprennent à être autonomes et à gérer leur temps. Cette configuration favorise également l’entraide entre les âges. Toutefois, ce modèle a ses limites : les enseignants sont parfois débordés, et l’accès aux ressources pédagogiques reste limité dans les zones rurales. L’État tente de soutenir ces écoles à travers des plans d’investissement et la mise à disposition de matériel numérique. Néanmoins, les différences avec les établissements urbains persistent. De nombreux parents restent attachés à ce type d’école, estimant qu’il transmet des valeurs de proximité, d’écoute et de respect du rythme de chaque élève.","question":"Quelle conséquence pédagogique de l'organisation multiniveaux est soulignée ?","options":["Les classes de niveaux mixtes empêchent de suivre des rythmes individuels","La mise à disposition d'équipements explique à elle seule leur fonctionnement","Le nombre limité d'enseignants accroît le travail personnel sans échanges","L'organisation multiâge favorise entraide et autonomie malgré des contraintes"],"correct":"D","explanation":"Dans les classes multiniveaux, les plus jeunes apprennent à gérer leur temps et à s'entraider entre âges. Le texte souligne aussi les difficultés des enseignants et des ressources."},{"number":39,"points":33,"passage":"L’usage des trottinettes électriques en ville a connu une explosion ces dernières années. D’abord perçues comme un gadget urbain, elles sont devenues un véritable moyen de transport, surtout chez les jeunes actifs. Leur coût relativement bas, la facilité d’utilisation, et la possibilité d’éviter les embouteillages expliquent en partie leur succès. Cependant, leur présence massive sur les trottoirs soulève des inquiétudes. Des accidents se produisent régulièrement, parfois graves, impliquant piétons, cyclistes ou automobilistes. De nombreuses municipalités ont réagi en instaurant des règles strictes : interdiction sur les trottoirs, limitation de la vitesse, port du casque recommandé, voire retrait de certaines entreprises de location. Cette régulation vise à encadrer un phénomène qui, mal maîtrisé, pourrait nuire à la sécurité et à la cohabitation en ville. L’avenir des trottinettes électriques dépendra donc de leur intégration harmonieuse dans l’espace urbain.","question":"Quelle condition détermine l'intégration future des trottinettes ?","options":["La pérennité du service suppose de régler la cohabitation avec les autres usagers","Le succès de l'usage permettrait de réduire progressivement les contraintes de circulation","Le développement des locations conditionne l'efficacité des règles de sécurité","La possibilité d'éviter les embouteillages rendrait secondaire l'occupation des trottoirs"],"correct":"A","explanation":"A. L'avenir de ces véhicules est explicitement subordonné à une intégration sûre dans l'espace urbain. Popularité et avantages pratiques ne suffisent pas."}]}$paper$::jsonb),
('tcf-reading-02','tcf-reading-2026-11-advanced-v5',$paper${"id":"tcf-reading-02","version":"tcf-reading-2026-11-advanced-v5","title":"TCF Reading · Test 02","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible.\n\nLes objets oubliés seront placés sous l'abri. L'entreprise doit pouvoir circuler librement avec son matériel de lavage.","question":"Que faut-il faire mardi soir ?","options":["Nettoyer les escaliers","Retirer les vélos de la cour","Fermer le local à vélos","Rapporter les clés"],"correct":"B","explanation":"Le passage indique : « Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible. » Cela justifie la réponse : Retirer les vélos de la cour."},{"number":2,"points":3,"passage":"Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi.\n\nUn message vocal précisera la nature du problème.","question":"Quand faut-il appeler le numéro affiché ?","options":["En cas de fuite urgente","Pour changer de boîte aux lettres","Pour réserver une visite","Pour payer le loyer"],"correct":"A","explanation":"Le passage indique : « Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi. » Cela justifie la réponse : En cas de fuite urgente."},{"number":3,"points":3,"passage":"La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques.\n\nL'ancienne adresse accueillera des travaux. Les dossiers déjà ouverts seront transférés automatiquement, sans nouvelle inscription des habitants concernés.","question":"Qu'est-ce qui change ?","options":["Le lieu des rendez-vous","Le prix du service","Les pièces à fournir","Les jours d'ouverture"],"correct":"A","explanation":"Le passage indique : « La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques. » Cela justifie la réponse : Le lieu des rendez-vous."},{"number":4,"points":3,"passage":"Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits.\n\nCette règle s'applique aussi aux invités. Le portail sera fermé chaque soir par le responsable de permanence, après vérification des lieux.","question":"Quelle activité est autorisée ?","options":["Entrer après vingt heures","Allumer un barbecue","Organiser un feu de bois","Prendre son déjeuner au jardin"],"correct":"D","explanation":"Le passage indique : « Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits. » Cela justifie la réponse : Prendre son déjeuner au jardin."},{"number":5,"points":9,"passage":"Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus.\n\nUne collègue m'a parlé d'un immeuble bien situé où une chambre se libère bientôt.","question":"Quel critère Nora doit-elle comprendre comme prioritaire ?","options":["La taille de la chambre","La présence d'un balcon","Le prix le plus bas possible","La facilité des trajets"],"correct":"D","explanation":"Le passage indique : « Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus. » Cela justifie la réponse : La facilité des trajets."},{"number":6,"points":9,"passage":"Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience.\n\nLe camion restera devant notre entrée pendant le déchargement.","question":"Pourquoi ce message est-il envoyé ?","options":["Annoncer une panne durable","Demander un changement d'étage","Prévenir d'une gêne temporaire","Interdire l'usage de l'ascenseur"],"correct":"C","explanation":"Le passage indique : « Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience. » Cela justifie la réponse : Prévenir d'une gêne temporaire."},{"number":7,"points":9,"passage":"Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement.\n\nJe filmerai chaque pièce et lui transmettrai les photographies des relevés. Il vérifiera ensuite le document avant que nous le signions ensemble.","question":"Comment le propriétaire participera-t-il ?","options":["À distance","Par courrier uniquement","En venant dimanche soir","En passant chez un voisin"],"correct":"A","explanation":"Le passage indique : « Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement. » Cela justifie la réponse : À distance."},{"number":8,"points":9,"passage":"L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place.\n\nDeux séances sont proposées samedi pour les personnes qui travaillent en semaine.","question":"Quel service est proposé ?","options":["Collecter les coordonnées des participants","Aider à comprendre un contrat","Signer un bail pour le locataire","Trouver un appartement garanti"],"correct":"B","explanation":"Le passage indique : « L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place. » Cela justifie la réponse : Aider à comprendre un contrat."},{"number":9,"points":9,"passage":"Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues.\n\nUne rencontre préalable permettra de discuter des habitudes de chacun.","question":"Quelle obligation accompagne l'hébergement ?","options":["Verser un salaire à l'hôte","Assurer des soins quotidiens","Être présent certains soirs","Travailler toutes les nuits"],"correct":"C","explanation":"Le passage indique : « Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues. » Cela justifie la réponse : Être présent certains soirs."},{"number":10,"points":9,"passage":"Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé.\n\nLes documents seront envoyés auparavant pour que chacun puisse les lire.","question":"Pourquoi l'horaire a-t-il été modifié ?","options":["Faciliter la participation des parents","Terminer des travaux urgents","Réduire le nombre de participants","Ajouter un vote supplémentaire"],"correct":"A","explanation":"Le passage indique : « Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé. » Cela justifie la réponse : Faciliter la participation des parents."},{"number":11,"points":15,"passage":"Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins.\n\nLe conseil a donc installé un tableau rappelant les heures de début et de fin. Les habitants peuvent échanger leur réservation s'ils préviennent la personne suivante. Une réunion permettra de discuter des incidents après un mois d'essai. Plusieurs familles apprécient déjà de ne plus devoir entretenir une grosse machine dans leur appartement. La réussite du service dépend cependant des petites attentions de chacun, notamment du nettoyage après utilisation.","question":"Quelle difficulté est signalée ?","options":["L'interdiction de laver chez soi","L'absence totale de réservation","La consommation excessive de papier","Le non-respect des créneaux"],"correct":"D","explanation":"Le passage indique : « Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins. » Cela justifie la réponse : Le non-respect des créneaux."},{"number":12,"points":15,"passage":"La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres.\n\nUne carte d'adhésion permet d'emprunter jusqu'à trois outils pour une semaine. Les appareils les plus délicats ne sont remis qu'après vérification des consignes. L'association a choisi de demander une participation annuelle modeste plutôt que de facturer chaque prêt.","question":"Quel est le rôle des bénévoles ?","options":["Vérifier les déclarations fiscales","Vendre les outils aux habitants","Expliquer l'utilisation du matériel","Rénover gratuitement les logements"],"correct":"C","explanation":"Le passage indique : « La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres. » Cela justifie la réponse : Expliquer l'utilisation du matériel."},{"number":13,"points":15,"passage":"Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir.\n\nLes architectes ont aussi gardé le grand escalier et créé des rangements individuels. Une association étudiante animera quelques soirées pendant les premiers mois, sans rendre la présence obligatoire. Les futurs locataires pourront visiter un étage témoin avant de déposer leur dossier. La ville espère ainsi proposer des chambres moins coûteuses tout en limitant la consommation de nouveaux matériaux.","question":"Quel choix guide le projet ?","options":["Réserver l'hôtel aux touristes","Construire des maisons séparées","Réutiliser un bâtiment existant","Supprimer les espaces communs"],"correct":"C","explanation":"Le passage indique : « Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir. » Cela justifie la réponse : Réutiliser un bâtiment existant."},{"number":14,"points":15,"passage":"Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien.\n\nElle a d'abord craint de manquer de place pour recevoir ses proches. Elle a finalement choisi une table pliante et utilise une chambre d'amis partagée dans la résidence lorsque sa famille reste dormir. Son budget de transport a également diminué. Elle ne présente pas son choix comme une solution convenant à tout le monde, mais comme un équilibre adapté à sa situation actuelle.","question":"Quel avantage Sarah découvre-t-elle ?","options":["Une pièce supplémentaire","Des meubles plus volumineux","Un garage gratuit","Un entretien moins important"],"correct":"D","explanation":"Le passage indique : « Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien. » Cela justifie la réponse : Un entretien moins important."},{"number":15,"points":15,"passage":"Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu.\n\nLes départs se font depuis le centre social et les circuits restent assez courts. Un bénévole répond aux questions pratiques, tandis que des commerçants présentent leurs services habituels. Les participants reçoivent une petite carte sur laquelle ils peuvent ajouter leurs propres repères. Le comité veut faciliter les premiers échanges entre voisins, sans demander aux nouveaux arrivants de connaître déjà quelqu'un.","question":"À quoi sert cette marche ?","options":["Collecter une taxe locale","Visiter seulement des monuments","Découvrir les services du quotidien","Vendre des abonnements touristiques"],"correct":"C","explanation":"Le passage indique : « Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu. » Cela justifie la réponse : Découvrir les services du quotidien."},{"number":16,"points":15,"passage":"Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire.\n\nLa température choisie, les absences et le nombre d'occupants modifient les besoins. Un logement montré vide peut aussi avoir été chauffé différemment. L'agence précise donc la période mesurée et la méthode utilisée. Les visiteurs sont invités à poser des questions sur l'isolation, plutôt qu'à retenir le seul montant affiché en tête de l'annonce.","question":"Comment faut-il interpréter ces chiffres ?","options":["Comme une indication dépendant de l'usage","Comme un prix fixe garanti","Comme le montant du dépôt","Comme une consommation toujours nulle"],"correct":"A","explanation":"Le passage indique : « Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire. » Cela justifie la réponse : Comme une indication dépendant de l'usage."},{"number":17,"points":15,"passage":"Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation.\n\nDes bénévoles passent proposer cet accueil aux personnes qui le souhaitent, sans les inscrire d'office. Une petite bibliothèque et des jeux sont disponibles, mais chacun peut simplement rester assis dans un lieu moins chaud. Le conseil des résidents évaluera le dispositif après l'été. Il regardera notamment si les horaires correspondent réellement aux besoins et si les personnes ayant du mal à marcher peuvent rejoindre facilement la salle commune.","question":"À qui cette mesure peut-elle particulièrement servir ?","options":["Aux propriétaires vendant leur logement","Aux résidents isolés pendant la chaleur","Aux touristes réservant une chambre","Aux automobilistes cherchant un parking"],"correct":"B","explanation":"Le passage indique : « Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation. » Cela justifie la réponse : Aux résidents isolés pendant la chaleur."},{"number":18,"points":15,"passage":"La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour.\n\nLa fête se tiendra donc près de l'entrée, où les tables peuvent être déplacées rapidement. Les voisins sont invités à apporter des plats froids pour éviter un équipement de cuisson encombrant. Une équipe vérifiera que les portes restent dégagées. Les organisateurs préfèrent modifier quelques habitudes plutôt que renoncer à accueillir tout le monde, y compris les personnes utilisant un fauteuil ou une poussette.","question":"Pourquoi la tente a-t-elle été écartée ?","options":["Elle gênerait un passage de sécurité","Elle empêcherait toute musique","Elle coûterait plus que le repas","Elle manquerait de places assises"],"correct":"A","explanation":"Le passage indique : « La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour. » Cela justifie la réponse : Elle gênerait un passage de sécurité."},{"number":19,"points":15,"passage":"Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende.\n\nLa première séance permettra surtout de préciser les horaires et les situations qui provoquent les désaccords. Chaque voisin pourra expliquer ce qu'il entend depuis son appartement et proposer un arrangement réaliste. Un document commun ne sera rédigé que si les personnes l'acceptent.","question":"Quelle est sa mission ?","options":["Décider du montant des loyers","Remplacer le gardien de nuit","Faciliter un accord entre voisins","Sanctionner immédiatement les habitants"],"correct":"C","explanation":"Le passage indique : « Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende. » Cela justifie la réponse : Faciliter un accord entre voisins."},{"number":20,"points":21,"passage":"Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées. Les membres prépareront ensemble les règles d'utilisation des espaces partagés. Certaines dépenses seront mutualisées, mais chaque ménage conservera son logement privé. Des réunions ouvertes permettront aux nouveaux participants de comprendre le fonctionnement avant de confirmer leur engagement. Le groupe cherche une solution durable plutôt qu'un simple placement immobilier individuel. Les comptes seront présentés régulièrement à tous les membres du groupe.","question":"Quel principe est retenu ?","options":["La suppression des assemblées","Des votes proportionnels à la richesse","Une participation sans domination financière","La réservation des décisions aux investisseurs"],"correct":"C","explanation":"Le passage indique : « Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées. » Cela justifie la réponse : Une participation sans domination financière."},{"number":21,"points":21,"passage":"Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients. Les personnes passent leur commande auprès de leur boutique habituelle et choisissent un horaire de réception. La commune prend en charge une partie du transport pendant l'expérimentation. Une permanence téléphonique est maintenue pour celles qui n'utilisent pas internet.","question":"Que permet principalement ce service ?","options":["Remplacer les achats par des dons","Faciliter l'accès aux commerces locaux","Décider des menus des clients","Fermer les boutiques de proximité"],"correct":"B","explanation":"Le passage indique : « Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients. » Cela justifie la réponse : Faciliter l'accès aux commerces locaux."},{"number":22,"points":21,"passage":"Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique. Le système indique seulement le secteur où une intervention semble nécessaire. Les données sont effacées après un délai annoncé. Le bailleur souhaite limiter les dégâts matériels tout en évitant qu'un outil d'entretien devienne un moyen de surveiller la vie domestique.","question":"Quelle préoccupation a influencé le dispositif ?","options":["La suppression de l'entretien","L'augmentation du débit d'eau","Le contrôle des visiteurs","La protection de la vie privée"],"correct":"D","explanation":"Le passage indique : « Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique. » Cela justifie la réponse : La protection de la vie privée."},{"number":23,"points":21,"passage":"Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois. Les associations de commerçants ont soutenu le projet après avoir constaté plusieurs recrutements abandonnés faute de logement. La mairie ne promet pas une réponse à toutes les demandes : les places disponibles seront attribuées selon des critères publiés. Un bilan annuel précisera si l'alternance des publics correspond effectivement aux besoins recensés.","question":"Quelle logique suit la commune ?","options":["Adapter l'occupation à différents besoins annuels","Interdire toutes les locations touristiques","Fermer les appartements après l'été","Réserver les logements aux retraités"],"correct":"A","explanation":"Le passage indique : « Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois. » Cela justifie la réponse : Adapter l'occupation à différents besoins annuels."},{"number":24,"points":21,"passage":"Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente. Les premiers essais auront lieu pendant plusieurs semaines, en dehors des grands événements. Les personnes âgées et les parents pourront notamment indiquer les zones trop bruyantes ou trop exposées. Les agents observeront aussi les passages nécessaires aux livraisons.","question":"Pourquoi les bancs seront-ils mobiles ?","options":["Pour tester plusieurs aménagements","Pour éviter toute observation","Pour les louer chaque soir","Pour empêcher les rencontres"],"correct":"A","explanation":"Le passage indique : « Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente. » Cela justifie la réponse : Pour tester plusieurs aménagements."},{"number":25,"points":21,"passage":"Un bailleur propose de remplacer certaines réunions par un questionnaire. Les locataires acceptent le questionnaire, mais demandent de conserver un échange oral pour les sujets complexes. Ils estiment qu'une case cochée n'explique pas toujours une difficulté. Les représentants soulignent aussi que certaines personnes ont besoin de faire préciser une question avant d'y répondre. Ils proposent donc un document court envoyé à l'avance, puis un échange collectif sur les points les plus discutés.","question":"Quelle combinaison de démarches les représentants défendent-ils ?","options":["Combiner des réponses préparées avec un échange permettant de préciser les cas difficiles","Privilégier les réponses individuelles avant de remplacer les réunions collectives","Conserver les réunions pour les sujets ordinaires et utiliser le formulaire pour les exceptions","Recueillir d'abord les avis par oral afin de préparer ensuite une synthèse écrite"],"correct":"A","explanation":"Le questionnaire facilite une première consultation, mais les échanges sont maintenus pour préciser les situations complexes. La solution combine les deux canaux plutôt que d'en éliminer un."},{"number":26,"points":21,"passage":"La rénovation d'une rue inclut des arbres, mais leurs racines ne disposeront pas partout du même espace. Des habitants demandent de revoir le sous-sol avant la plantation. Ils craignent que des arbres mal installés dépérissent rapidement. Le service technique a accepté de présenter les emplacements des conduites et les volumes de terre disponibles. Plusieurs solutions seront comparées, dont le déplacement de quelques places de stationnement. Les riverains souhaitent éviter une succession de plantations coûteuses suivies de remplacements.","question":"Quelle démarche les habitants préconisent-ils pour éviter des remplacements répétés ?","options":["Revoir le sous-sol pour augmenter le nombre d'arbres plantés la première année","Choisir les espèces en fonction des emplacements de stationnement conservés","Étudier la répartition des conduites une fois les arbres déjà installés","Anticiper les contraintes souterraines avant d'implanter durablement les arbres"],"correct":"D","explanation":"L'espace disponible pour les racines et les conduites est vérifié avant la plantation afin d'éviter le dépérissement. Les arbitrages sur le stationnement restent des moyens possibles, pas l'objectif."},{"number":27,"points":21,"passage":"Une résidence supprime les petites poubelles individuelles dans ses espaces communs. Les déchets sont triés à un point unique. Le volume collecté baisse, mais le conseil rappelle qu'un déplacement du problème vers la rue annulerait ce bénéfice. Des observations seront réalisées autour du point de collecte pour repérer ce déplacement éventuel. Les habitants recevront un rappel sur les emballages acceptés et sur les horaires.","question":"Quelle condition limiterait la portée du résultat annoncé ?","options":["La baisse mesurée devrait être corrigée selon les horaires de collecte","Les nouvelles consignes peuvent expliquer une modification des déchets triés","Le volume moindre pourrait masquer des déchets abandonnés hors du point de collecte","Le regroupement des bacs réduit la quantité totale disponible pour le tri"],"correct":"C","explanation":"La quantité collectée baisse, mais le bénéfice disparaîtrait si les déchets étaient simplement jetés dans la rue. L'indicateur doit donc inclure les déplacements du problème."},{"number":28,"points":21,"passage":"Dans un quartier en pente, un service municipal accompagne les personnes âgées au marché. Les bénévoles portent les sacs, mais laissent les bénéficiaires choisir leurs achats et leur rythme. L'autonomie compte autant que l'aide matérielle. Avant la première sortie, le centre social demande quels commerces et quels jours conviennent à chaque personne. Les accompagnateurs peuvent aider à traverser ou à porter, mais ne gèrent pas le budget des courses.","question":"Quelle conception de l'aide se dégage de cette organisation ?","options":["Répartir les tâches selon les commerces que les bénévoles connaissent le mieux","Soutenir le déplacement sans se substituer aux décisions des personnes","Choisir les produits courants pour limiter le temps passé dans les magasins","Organiser les sorties en priorité selon les horaires des accompagnateurs"],"correct":"B","explanation":"Les bénévoles portent les sacs et peuvent sécuriser les trajets ; les personnes choisissent leurs achats, leur budget et leur rythme. L'aide ne se substitue pas aux décisions."},{"number":29,"points":21,"passage":"Une cour d'école devient accessible aux riverains le week-end. La convention prévoit un partage des frais de nettoyage. L'association de parents y voit une ouverture utile, à condition que les élèves retrouvent un lieu propre le lundi. Les premières ouvertures se feront sur un nombre limité de week-ends. Les riverains disposeront de poubelles supplémentaires et d'un numéro pour signaler un problème.","question":"Quelle réserve permet de concilier ouverture et usage scolaire ?","options":["Évaluer la fréquentation du week-end avant d'étendre le calendrier d'ouverture","Réserver le nettoyage aux équipes scolaires afin de garantir la sécurité des élèves","Ouvrir le lieu au public sous réserve de préserver son état pour la reprise des cours","Limiter les activités aux riverains qui participent aux frais d'entretien"],"correct":"C","explanation":"L'association accepte l'ouverture le week-end sous réserve de restituer un lieu propre aux élèves le lundi. Les autres mesures décrivent l'organisation, non la condition posée."},{"number":30,"points":26,"passage":"On présente souvent les immeubles partagés comme une réponse automatique à la solitude. Pourtant, un salon commun ne crée pas à lui seul des relations. Dans une résidence récente, les rencontres ont commencé lorsque des habitants ont proposé des activités souples, auxquelles chacun pouvait refuser de participer. Ces activités n'étaient pas obligatoirement longues : partager un café ou arroser les plantes a parfois suffi à commencer une conversation. Le dispositif a fonctionné parce qu'il laissait une marge de choix aux personnes les plus réservées.","question":"Quelle idée initiale l'auteur remet-il principalement en cause ?","options":["Des activités choisies librement pourraient faciliter les rencontres","La mise à disposition d'un salon suffirait à créer des relations entre habitants","Des échanges informels pourraient encourager les personnes réservées","De courtes activités partagées pourraient être le début d'un lien"],"correct":"B","explanation":"Les contacts ne viennent pas automatiquement de l'existence du salon. Ils naissent d'activités facultatives adaptées aux habitants, même brèves."},{"number":31,"points":26,"passage":"La ville mesure la réussite de ses rénovations par le nombre de façades refaites. Un urbaniste demande d'ajouter le confort d'été et les charges des occupants. Une façade plus belle peut masquer un appartement encore coûteux à chauffer. L'apparence ne suffit donc pas à apprécier les effets d'une intervention. Des entretiens avec les habitants pourraient compléter les relevés techniques.","question":"Quel enrichissement des critères l'urbaniste réclame-t-il ?","options":["Les entretiens peuvent être remplacés par un relevé des dépenses de chauffage","Les conditions vécues par les occupants doivent compléter les chiffres de rénovation","L'amélioration des façades doit être mesurée avant les effets de confort","La perception des habitants doit remplacer les indicateurs techniques"],"correct":"B","explanation":"La ville comptait surtout les façades rénovées ; l'urbaniste ajoute confort et charges réelles, avec des entretiens en complément des mesures techniques."},{"number":32,"points":26,"passage":"Un café de quartier accueille les réunions associatives sans exiger de consommation. Cette ouverture attire des habitants qui ne fréquentaient pas le lieu. Pour financer les soirées, le gérant répartit les coûts entre location ponctuelle de salle et recettes habituelles. La gratuité pour les participants repose ainsi sur un équilibre économique précis. Le gérant examine régulièrement cet équilibre, car un événement réussi ne couvre pas nécessairement ses dépenses directes.","question":"Comment le café rend-il possible l'accès gratuit aux réunions ?","options":["Les nouvelles réunions attirent des habitants, ce qui finance directement la gratuité","Les recettes d'autres activités permettent de couvrir le coût des soirées associatives","Le gérant compense l'absence de consommation par une obligation de louer la salle","Chaque soirée associative devient rentable lorsque les participants sont nombreux"],"correct":"B","explanation":"B. Le gérant répartit les coûts entre locations ponctuelles et recettes ordinaires, plutôt que de financer la réunion avec la consommation de ses participants."},{"number":33,"points":26,"passage":"Les petites surfaces sont parfois vantées pour leur sobriété. Ce raisonnement oublie les activités déplacées hors du logement : laverie, stockage ou déplacements supplémentaires. Un logement compact peut être économe si le quartier fournit des services accessibles. Sans cette proximité, la réduction de surface ne garantit pas une réduction des dépenses. Il faut donc regarder où se trouvent les services et qui peut les utiliser.","question":"Quelle condition nuance les avantages d'un petit logement ?","options":["Les équipements partagés à proximité comptent dans le bilan réel d'une petite surface","La diminution de la surface permet de réduire les déplacements indépendamment du quartier","Les ménages économisent surtout lorsque les services sont plus éloignés du domicile","L'accès aux services joue un rôle secondaire par rapport au seul nombre de mètres carrés"],"correct":"A","explanation":"A. La sobriété globale dépend de services voisins accessibles; les usages reportés hors du logement peuvent annuler les économies apparentes."},{"number":34,"points":26,"passage":"Pour attribuer des jardins familiaux, une ville utilisait uniquement l'ancienneté de la demande. Elle réserve désormais quelques parcelles aux personnes sans espace extérieur et organise un renouvellement partiel. Cette modification rend l'accès moins prévisible pour les anciens inscrits, mais élargit les profils des bénéficiaires. Elle souhaite conserver une certaine stabilité pour les jardiniers déjà engagés, sans transformer une liste ancienne en droit permanent excluant toutes les nouvelles demandes.","question":"Sur quelle tension repose le nouveau mode d'attribution ?","options":["Élargir l'accès en renonçant progressivement à toute stabilité des parcelles","Accorder davantage de droits aux inscrits de longue date avant d'ouvrir","Modifier les critères seulement lors du départ définitif d'un jardinier","Préserver la continuité des usages tout en répondant à des besoins nouveaux"],"correct":"D","explanation":"La ville conserve une part de stabilité tout en réservant quelques parcelles aux personnes sans extérieur. Elle arbitre entre ancienneté et besoins nouveaux."},{"number":35,"points":26,"passage":"Les commerces au rez-de-chaussée participent à l'animation d'une rue. Pourtant, certaines activités gênent les riverains par leurs livraisons ou leurs horaires. Une association refuse de choisir entre une rue vide et une activité sans règles. Elle défend des accords locaux qui maintiennent les services tout en limitant les nuisances. Les horaires de livraison et les équipements d'isolation peuvent faire partie des solutions.","question":"Quelle solution l'association préfère-t-elle à une opposition de principe ?","options":["Restreindre les livraisons en laissant aux commerçants la totalité des coûts d'adaptation","Conserver les activités en demandant aux riverains de s'adapter à leurs horaires","Maintenir les services en négociant localement des mesures contre les nuisances","Autoriser les commerces calmes à condition que les autres quittent le quartier"],"correct":"C","explanation":"C. L'association défend des accords sur horaires et isolation, sans faire disparaître les commerces ni laisser les nuisances inchangées."},{"number":36,"points":33,"passage":"Une ville annonce des logements « abordables » en comparant leurs loyers à ceux des annonces privées les plus récentes. Une chercheuse remarque que cette comparaison ignore les revenus des ménages visés. Un prix inférieur au marché peut encore absorber une part excessive du budget d'une famille. Elle ne rejette pas le programme, mais demande de préciser pour qui il devient accessible. L'abordabilité doit donc être appréciée par rapport aux ressources des occupants, et pas seulement aux prix voisins. Pour les promoteurs du programme, le prix inférieur reste un progrès par rapport aux offres voisines. La chercheuse leur propose de publier également plusieurs exemples de budgets, avec les charges et les trajets quotidiens. Une famille peut en effet accepter un loyer modéré puis supporter des dépenses importantes pour rejoindre son travail.","question":"Pourquoi la qualification d'« abordable » reste-t-elle discutable ?","options":["La différence de loyer ne serait pertinente que si le programme réduisait les charges","Les loyers des annonces récentes sous-estiment nécessairement les prix réellement payés","La comparaison devrait porter principalement sur le nombre d'appartements proposés","Le prix inférieur au marché peut rester trop élevé au regard du budget des ménages"],"correct":"D","explanation":"D. La critique porte sur l'absence de référence aux ressources, charges et trajets des ménages, pas seulement sur la différence de prix avec le marché."},{"number":37,"points":33,"passage":"Une résidence organise chaque semaine un repas partagé. Au début, le conseil souhaitait rendre la présence obligatoire pour lutter contre l'isolement. Plusieurs habitants ont expliqué qu'ils travaillaient le soir ou préféraient des rencontres moins nombreuses. Le projet a été revu : chacun peut proposer un autre créneau ou participer autrement. L'objectif de convivialité est conservé, mais il ne justifie plus une obligation identique pour tous. Au départ, les promoteurs de la résidence craignaient que les logements privés ne favorisent le repli de chacun. Ils ont ensuite constaté que les échanges étaient plus faciles lorsque les habitants pouvaient choisir leurs moments de présence. Des personnes peu disponibles ont proposé de préparer une liste de courses ou de participer à une sortie occasionnelle. Ces formes de contribution ont enrichi le projet.","question":"Quel ajustement explique le maintien de l'objectif initial ?","options":["Maintenir une présence hebdomadaire en laissant choisir seulement le créneau horaire","Remplacer la participation commune par une aide individuelle à domicile","Distinguer les résidents selon leur disponibilité pour prévoir des repas obligatoires","Conserver la convivialité en diversifiant les moments et les formes d'engagement"],"correct":"D","explanation":"Le conseil abandonne l'obligation identique et admet plusieurs créneaux ou formes de participation, tout en conservant le projet de convivialité."},{"number":38,"points":33,"passage":"À l'occasion d'une rénovation, un quartier reçoit une nouvelle image dans les brochures touristiques. Ses commerces et ses places deviennent plus attractifs. Cependant, plusieurs ateliers anciens quittent les lieux après une hausse des loyers. Les responsables célèbrent la fréquentation, tandis que des habitants regrettent la disparition de services familiers. Le renouvellement urbain peut améliorer l'attractivité tout en fragilisant certaines fonctions qui faisaient vivre le quartier. Les responsables des ateliers ne contestent pas que la place soit devenue plus agréable. Ils expliquent cependant que leur clientèle habituelle et leurs réseaux d'entraide s'étaient formés sur une longue période. Un départ à quelques kilomètres peut déjà rompre ces relations. La commune étudie donc des locaux à loyer encadré et un accompagnement des activités menacées. Le débat porte moins sur le choix entre amélioration et immobilité que sur la manière de répartir les bénéfices du changement entre visiteurs, nouveaux investisseurs et habitants déjà présents.","question":"Quel effet paradoxal la transformation du quartier peut-elle avoir ?","options":["Le départ des ateliers s'explique surtout par le recul de l'intérêt des visiteurs","Les travaux renforcent la fréquentation mais affaiblissent les réseaux économiques préexistants","Les loyers augmentent parce que les ateliers les plus anciens cessent d'attirer","L'amélioration des places réduit la demande des commerçants pour ces locaux"],"correct":"B","explanation":"B. L'attractivité augmente mais les loyers provoquent des départs et fragilisent la vie économique locale."},{"number":39,"points":33,"passage":"Pour construire plus vite, une municipalité veut uniformiser les plans de ses futurs logements. Des architectes reconnaissent que certains éléments techniques peuvent être répétés. Ils contestent toutefois l'idée qu'une même distribution conviendrait à un étudiant, à une famille et à une personne qui travaille chez elle. Leur proposition conserve des composants communs tout en permettant des transformations. L'économie de moyens devient pertinente lorsqu'elle rend l'adaptation possible au lieu d'effacer la diversité des usages. L'équipe travaille par exemple sur des cloisons faciles à déplacer et des pièces capables de changer de fonction. Elle demande aussi de prévoir les accès techniques avant la construction, car une transformation devient vite coûteuse lorsque toutes les installations sont fixées au même endroit. Les élus souhaitent comparer le coût initial et celui des adaptations futures.","question":"Quel principe de conception est retenu par les architectes ?","options":["L'uniformité de tous les logements limite les coûts dès lors que les occupants sont différents","Les adaptations doivent être décidées après la construction pour réduire les dépenses initiales","L'usage d'éléments réutilisables dispense de prévoir l'accès aux installations","Une base technique commune peut s'accompagner d'aménagements modulables selon les usages"],"correct":"D","explanation":"D. Les architectes acceptent les composants répétés, tout en prévoyant des cloisons mobiles et des accès techniques permettant des adaptations."}]}$paper$::jsonb),
('tcf-reading-03','tcf-reading-2026-11-advanced-v5',$paper${"id":"tcf-reading-03","version":"tcf-reading-2026-11-advanced-v5","title":"TCF Reading · Test 03","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale.\n\nUne affiche devant la réception rappellera le parcours d'accès.","question":"Qu'est-ce qui est maintenu ?","options":["L'accueil toute la journée","Les cours de l'après-midi","Les inscriptions du soir","L'entrée principale ouverte"],"correct":"B","explanation":"Le passage indique : « L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale. » Cela justifie la réponse : Les cours de l'après-midi."},{"number":2,"points":3,"passage":"Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles.\n\nL'animateur vous aidera à sélectionner les expériences pertinentes.","question":"Que faut-il apporter ?","options":["Un contrat signé","Une offre d'emploi","Une lettre de recommandation","Un ordinateur"],"correct":"B","explanation":"Le passage indique : « Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles. » Cela justifie la réponse : Une offre d'emploi."},{"number":3,"points":3,"passage":"Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis.\n\nUn agent ouvrira une pièce de stockage pour les effets personnels.","question":"Quand faut-il libérer les casiers ?","options":["Lundi après les travaux","Mardi matin","À la fin du mois","Avant dimanche soir"],"correct":"D","explanation":"Le passage indique : « Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis. » Cela justifie la réponse : Avant dimanche soir."},{"number":4,"points":3,"passage":"La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes.\n\nLes personnes sans caméra pourront participer avec le son seulement. Les documents de travail seront transmis avec l'invitation à tous les collègues.","question":"Quel changement est annoncé ?","options":["La durée de la réunion","Le jour de la réunion","Le nom du responsable","Le mode de participation"],"correct":"D","explanation":"Le passage indique : « La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes. » Cela justifie la réponse : Le mode de participation."},{"number":5,"points":9,"passage":"Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient.\n\nJ'ai déjà vérifié avec le responsable que cet échange ne désorganiserait pas l'équipe. Merci de me répondre rapidement.","question":"Quel service l'auteur veut-il conserver ?","options":["Celui du mercredi","Celui du samedi","Celui du vendredi","Tous les services du matin"],"correct":"C","explanation":"Le passage indique : « Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient. » Cela justifie la réponse : Celui du vendredi."},{"number":6,"points":9,"passage":"Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage.\n\nLes dossiers seront traités dans un bureau calme avec un petit groupe.","question":"Quelle qualité est particulièrement recherchée ?","options":["La discrétion","Une expérience de direction","La maîtrise d'un camion","La connaissance de trois langues"],"correct":"A","explanation":"Le passage indique : « Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage. » Cela justifie la réponse : La discrétion."},{"number":7,"points":9,"passage":"J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille.\n\nJ'apprécie pourtant l'équipe et les missions annoncées. Peut-être pourrai-je envisager ce type de poste plus tard, lorsque l'organisation familiale sera différente.","question":"Pourquoi cette personne refuse-t-elle ?","options":["Le salaire serait réduit","Le poste disparaît prochainement","Les déplacements ne lui conviennent pas","Elle souhaite travailler à l'étranger"],"correct":"C","explanation":"Le passage indique : « J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille. » Cela justifie la réponse : Les déplacements ne lui conviennent pas."},{"number":8,"points":9,"passage":"La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement.\n\nUn salarié expliquera les équipements et les horaires.","question":"À quoi sert cette visite ?","options":["Remplacer l'entretien","Signer immédiatement le contrat","Mieux comprendre le travail proposé","Noter la vitesse des candidats"],"correct":"C","explanation":"Le passage indique : « La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement. » Cela justifie la réponse : Mieux comprendre le travail proposé."},{"number":9,"points":9,"passage":"Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale.\n\nLe planning sera affiché dans le vestiaire et envoyé aux personnes absentes.","question":"Quelles demandes peuvent encore être traitées ce mois-ci ?","options":["Toutes les demandes tardives","Les demandes sans justification professionnelle","Les urgences familiales","Seulement les demandes de congés d'été"],"correct":"C","explanation":"Le passage indique : « Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale. » Cela justifie la réponse : Les urgences familiales."},{"number":10,"points":9,"passage":"L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée.\n\nLes candidats découvriront plusieurs étapes du travail avant de choisir une spécialité. L'école et l'entreprise feront régulièrement le point sur les progrès réalisés.","question":"Comment l'apprentissage sera-t-il organisé ?","options":["Uniquement à domicile","Entre formation et travail accompagné","Sans présence en entreprise","Par un examen quotidien éliminatoire"],"correct":"B","explanation":"Le passage indique : « L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée. » Cela justifie la réponse : Entre formation et travail accompagné."},{"number":11,"points":15,"passage":"Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur.\n\nElle connaît déjà les dossiers et les habitudes des clients, mais les logiciels ont beaucoup changé pendant son absence. Le centre lui a proposé une évaluation préalable pour identifier ses priorités. Elle suit maintenant deux séances par semaine et s'exerce entre les cours sur des cas proches de son ancien travail. Cette progression lui permet de retrouver confiance sans devoir recommencer toutes ses études depuis le début.","question":"Quel est son objectif ?","options":["Devenir formatrice immédiatement","Ouvrir une agence de voyages","Abandonner son secteur","Mettre ses compétences à jour"],"correct":"D","explanation":"Le passage indique : « Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur. » Cela justifie la réponse : Mettre ses compétences à jour."},{"number":12,"points":15,"passage":"Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions.\n\nLes nouveaux employés y trouvent des exemples concrets, avec les causes possibles d'une panne et les vérifications à effectuer avant de remplacer une pièce. Les remarques doivent être relues par un collègue pour éviter de diffuser une consigne imprécise.","question":"Qu'est-ce qui caractérise ce carnet ?","options":["Il est réservé aux clients","Il reste définitivement inchangé","Il remplace toutes les formations","Il s'enrichit de l'expérience du terrain"],"correct":"D","explanation":"Le passage indique : « Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions. » Cela justifie la réponse : Il s'enrichit de l'expérience du terrain."},{"number":13,"points":15,"passage":"Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique.\n\nLe groupe travaille d'abord sur des chutes de matière afin de pouvoir recommencer sans gaspiller une pièce coûteuse. L'artisan observe la position des mains et demande à chacun d'expliquer son choix. Les échanges révèlent souvent qu'un geste apparemment simple combine plusieurs décisions. À la fin, les participants rédigent quelques repères personnels. Ils savent qu'une fiche ne remplacera pas l'expérience, mais qu'elle pourra leur rappeler les points essentiels lorsqu'ils pratiqueront seuls dans leur propre atelier.","question":"Quelle approche privilégie-t-il ?","options":["L'essai accompagné","L'observation sans exercice","La mémorisation des tarifs","Le travail sans retour"],"correct":"A","explanation":"Le passage indique : « Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique. » Cela justifie la réponse : L'essai accompagné."},{"number":14,"points":15,"passage":"La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil.\n\nLe prêt dure tout le cycle et comprend une courte présentation du matériel. Les apprenants peuvent ainsi reprendre les exercices entre les séances, même si leur ordinateur familial est partagé ou ancien. Une permanence permet de signaler un problème technique. La bibliothèque ne demande pas aux participants de détailler leurs revenus ; elle souhaite simplement que les conditions matérielles ne décident pas à elles seules de la possibilité de suivre le cours.","question":"Qui peut bénéficier du prêt ?","options":["Seulement les formateurs","Les entreprises achetant un abonnement","Uniquement des chômeurs inscrits","Des personnes aux situations professionnelles variées"],"correct":"D","explanation":"Le passage indique : « La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil. » Cela justifie la réponse : Des personnes aux situations professionnelles variées."},{"number":15,"points":15,"passage":"Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne.\n\nLes salariés s'organisent avec leurs collègues et indiquent leur créneau sur un tableau. Un changement est possible si les personnes concernées se mettent d'accord. La direction évaluera l'essai après plusieurs semaines, en regardant les files au restaurant et le fonctionnement de l'atelier. Certains employés apprécient de pouvoir déjeuner plus tôt ; d'autres préfèrent attendre un moment calme. La règle commune permet cette diversité sans laisser une équipe entière quitter son poste simultanément.","question":"Quelle limite encadre cette souplesse ?","options":["L'obligation de manger ensemble","Le maintien du fonctionnement de la ligne","La suppression de toutes les pauses","L'autorisation préalable des clients"],"correct":"B","explanation":"Le passage indique : « Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne. » Cela justifie la réponse : Le maintien du fonctionnement de la ligne."},{"number":16,"points":15,"passage":"Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard.\n\nL'exercice est court et utilise des documents fictifs pour ne pas transformer le recrutement en travail gratuit pour l'entreprise. Deux personnes relisent les résultats avec la même grille. Le cabinet souhaite donner leur chance à des parcours moins connus, sans promettre que l'origine scolaire n'aura jamais d'importance.","question":"Que cherche ce procédé ?","options":["Examiner d'abord les compétences en situation","Éliminer toute personne diplômée","Choisir les candidats les plus jeunes","Supprimer l'entretien avec le candidat"],"correct":"A","explanation":"Le passage indique : « Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard. » Cela justifie la réponse : Examiner d'abord les compétences en situation."},{"number":17,"points":15,"passage":"Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion.\n\nElle rencontre également des professionnels pour connaître les horaires, les charges et les périodes plus calmes de cette activité. Une journée d'observation lui a permis de voir le travail derrière le comptoir, au-delà des réparations les plus intéressantes. Elle constitue progressivement un budget et vérifie les débouchés dans sa ville. Ses proches l'encouragent, mais elle préfère décider à partir de ces informations plutôt que quitter son poste après quelques cours seulement.","question":"Pourquoi garde-t-elle son emploi ?","options":["Parce que la formation est déjà terminée","Pour avancer prudemment dans son projet","Pour devenir responsable du cours","Parce qu'elle renonce au métier envisagé"],"correct":"B","explanation":"Le passage indique : « Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion. » Cela justifie la réponse : Pour avancer prudemment dans son projet."},{"number":18,"points":15,"passage":"Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges.\n\nLes responsables souhaitent réduire les questions restées sans réponse parce qu'il était difficile de trouver un moment disponible. Les sujets collectifs feront l'objet d'une réunion séparée. Le service rappelle que cette organisation ne change pas les règles applicables, mais doit rendre leur explication plus accessible aux personnes qui hésitent à poser une question devant toute l'équipe.","question":"Quelle précaution est prise ?","options":["Préserver la confidentialité des échanges","Diffuser les questions à toute l'équipe","Enregistrer toutes les conversations publiquement","Recevoir uniquement des groupes"],"correct":"A","explanation":"Le passage indique : « Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges. » Cela justifie la réponse : Préserver la confidentialité des échanges."},{"number":19,"points":15,"passage":"Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification.\n\nLes fiches seront mises à jour lorsque les recettes ou les fournisseurs changent. L'équipe apprend aussi à transmettre clairement une demande particulière, sans l'interpréter de mémoire. Il précise qu'il vaut mieux prendre quelques minutes pour obtenir une confirmation que donner une assurance que la cuisine ne peut pas réellement tenir.","question":"Quel comportement est demandé ?","options":["Vérifier les informations incertaines","Rassurer le client sans consulter personne","Éviter toute conversation avec la cuisine","Supprimer tous les plats du menu"],"correct":"A","explanation":"Le passage indique : « Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification. » Cela justifie la réponse : Vérifier les informations incertaines."},{"number":20,"points":21,"passage":"Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants. Les participants peuvent interrompre temporairement leur parcours et reprendre les éléments déjà validés. Un entretien régulier permet de vérifier si le rythme reste compatible avec leur emploi. Le centre souhaite rendre la formation accessible sans réduire les compétences attendues à la fin. Il demande donc un engagement réaliste plutôt qu'une présence intensive impossible à maintenir pour certaines personnes.","question":"Quel avantage offre l'évaluation initiale ?","options":["Garantir le diplôme sans formation","Imposer le même calendrier à chacun","Supprimer tous les examens","Éviter des apprentissages déjà maîtrisés"],"correct":"D","explanation":"Le passage indique : « Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants. » Cela justifie la réponse : Éviter des apprentissages déjà maîtrisés."},{"number":21,"points":21,"passage":"Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante. Les conducteurs ont identifié des arrêts où les attentes sont longues et des itinéraires qui imposent de nombreuses manœuvres. Leurs propositions seront comparées sur des journées semblables. La direction souhaite éviter qu'un meilleur délai annoncé se traduise simplement par davantage de pression sur les mêmes personnes.","question":"Quels critères seront comparés ?","options":["Uniquement le prix des véhicules","La performance et les conditions de travail","Le nombre de publicités affichées","Les préférences musicales des conducteurs"],"correct":"B","explanation":"Le passage indique : « Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante. » Cela justifie la réponse : La performance et les conditions de travail."},{"number":22,"points":21,"passage":"Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent. Les bénévoles apportent des exemples, des documents et des descriptions de situations. Un accompagnateur les aide à distinguer une responsabilité précise d'une participation occasionnelle. Ils n'effacent pas les exigences du diplôme demandé, mais peuvent aider une personne à présenter des acquis jusque-là difficiles à formuler.","question":"Quelle limite du service est précisée ?","options":["Seuls les salariés sont reçus","L'accompagnement ne garantit pas la certification","Le bénévolat ne peut jamais être décrit","L'association délivre tous les diplômes"],"correct":"B","explanation":"Le passage indique : « Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent. » Cela justifie la réponse : L'accompagnement ne garantit pas la certification."},{"number":23,"points":21,"passage":"Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations. Les nouvelles règles ont été dessinées avec les salariés après une semaine d'observation. Chacun peut signaler une difficulté sans demander l'interdiction de tous les échanges. Les responsables savent que les dossiers ne demandent pas tous le même environnement.","question":"Pourquoi l'organisation a-t-elle évolué ?","options":["Pour concilier échange et concentration","Pour interdire tout travail collectif","Pour augmenter le bruit des appels","Pour réduire le nombre de clients"],"correct":"A","explanation":"Le passage indique : « Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations. » Cela justifie la réponse : Pour concilier échange et concentration."},{"number":24,"points":21,"passage":"Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun. Les premiers essais concerneront des périodes courtes, avec une personne expérimentée disponible pour répondre aux questions. Les volontaires apprendront aussi les procédures à suivre en cas d'incident. La direction souhaite limiter les remplacements improvisés au dernier moment.","question":"Quel objectif poursuit l'hôtel ?","options":["Imposer des nuits à tous les clients","Remplacer tout le personnel par une machine","Rendre le service moins dépendant d'une personne","Supprimer les repos"],"correct":"C","explanation":"Le passage indique : « Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun. » Cela justifie la réponse : Rendre le service moins dépendant d'une personne."},{"number":25,"points":21,"passage":"Les salariés d'une petite entreprise choisissent les sujets de leur journée annuelle de formation. Certains demandent des outils immédiatement utiles, d'autres un temps de réflexion sur leur métier. Le programme final conserve les deux approches. Les responsables ont demandé aux participants de préciser leurs attentes avant la journée. Les ateliers pratiques seront suivis d'un échange sur les situations où les outils pourraient réellement servir. Le service ne veut pas accumuler des présentations sans lien avec les missions.","question":"Quel compromis est trouvé ?","options":["Réserver la réflexion générale à une séance distincte des exercices techniques","Conserver les outils pratiques en supprimant les échanges sur les situations réelles","Associer l'apprentissage d'outils à une discussion de leur utilisation au travail","Adapter la formation aux attentes individuelles sans maintenir de programme commun"],"correct":"C","explanation":"Les salariés ont demandé des outils pratiques et du recul sur leur métier ; le programme combine exercices et discussion sur leur usage."},{"number":26,"points":21,"passage":"Une école professionnelle invite d'anciens élèves ayant changé plusieurs fois de métier. Elle veut montrer des parcours rarement linéaires, plutôt que présenter une seule trajectoire idéale. Les témoignages portent aussi sur les hésitations et les échecs. Certains racontent une première orientation abandonnée, d'autres une formation reprise après plusieurs années de travail. Les élèves pourront interroger les intervenants sur les ressources qui les ont aidés à rebondir. L'école souhaite présenter des expériences concrètes plutôt que transformer chaque témoignage en leçon de réussite personnelle.","question":"Que souhaitent montrer les organisateurs ?","options":["Illustrer des reconversions surtout provoquées par des difficultés scolaires","Inciter les élèves à changer de métier pour multiplier leurs compétences","Présenter les carrières variées comme la conséquence des formations continues","Montrer que les parcours professionnels peuvent évoluer et comporter des hésitations"],"correct":"D","explanation":"Les témoignages présentent des changements de métier, des hésitations et des formations reprises. L'objectif est d'élargir la représentation des trajectoires possibles."},{"number":27,"points":21,"passage":"Un atelier réserve du temps à la transmission avant le départ d'un salarié expérimenté. Des vidéos seront réalisées, mais elles seront accompagnées de séances pratiques. Certaines décisions dépendent de sensations que l'image seule explique mal. Le technicien partant à la retraite a proposé de commenter des interventions réelles avec les nouveaux salariés. L'équipe réservera quelques heures à ces échanges avant son départ.","question":"Pourquoi les vidéos ne suffisent-elles pas ?","options":["Les vidéos peuvent montrer les gestes, mais leur ordre de réalisation doit rester flexible","Les décisions dépendent aussi de sensations difficiles à transmettre par l'image","Le tournage ne permet pas de recueillir les questions posées pendant les interventions","L'apprentissage pratique concerne surtout les salariés ayant déjà vu les vidéos"],"correct":"B","explanation":"Des gestes ou décisions dépendent de sensations et de situations que les vidéos transmettent mal. Les séances pratiques complètent les enregistrements."},{"number":28,"points":21,"passage":"Une enquête interne révèle que des employés n'utilisent pas leur droit à la formation. Les horaires proposés coïncident avec leurs obligations familiales. La direction ajoute des créneaux différents plutôt que conclure à un manque de motivation. Les employés expliquent qu'ils doivent parfois choisir entre une séance et un rendez-vous déjà prévu pour leurs enfants. D'autres travaillent sur des rotations qui varient d'une semaine à l'autre. Le service propose désormais plusieurs dates et un court accompagnement individuel pour les absences justifiées.","question":"Quelle interprétation est privilégiée ?","options":["Les employés préfèrent reporter leur formation plutôt que de changer de sujet","Les rotations de service rendent le contenu des cours difficile à choisir","Le manque d'accompagnement explique la totalité des absences signalées","Les horaires offerts empêchent certains salariés de profiter des formations"],"correct":"D","explanation":"Les créneaux coïncident avec les contraintes familiales et professionnelles. La direction agit sur l'accès concret plutôt que d'inférer une faible motivation."},{"number":29,"points":21,"passage":"Un espace de travail propose des bureaux à la journée. Plusieurs indépendants apprécient la souplesse, mais demandent une formule stable pour retrouver les mêmes voisins. La liberté de venir ponctuellement ne répond pas à tous les besoins de relation professionnelle. Le gestionnaire ajoute donc quelques tables réservables plusieurs semaines de suite, sans imposer cette formule à tous. Les indépendants occasionnels peuvent toujours venir à la journée.","question":"Quel besoin supplémentaire apparaît ?","options":["La stabilité des horaires de bureau faciliterait la préparation des dossiers complexes","Le retour régulier des mêmes personnes permettrait de nouer des relations professionnelles","L'accès à plusieurs salles améliorerait la disponibilité des postes ponctuels","Le maintien des réservations à la journée rendrait l'espace plus prévisible"],"correct":"B","explanation":"Certains indépendants veulent retrouver les mêmes personnes au fil des semaines. Les tables réservables répondent à un besoin de continuité sans supprimer les bureaux ponctuels."},{"number":30,"points":26,"passage":"Une entreprise compte les heures de connexion pour évaluer le travail à distance. Une représentante du personnel remarque qu'une présence numérique longue ne dit rien de la difficulté des dossiers traités. Elle propose d'étudier les résultats avec les salariés, tout en tenant compte du temps nécessaire pour les obtenir. Elle suggère également de suivre les difficultés rencontrées dans les dossiers. Un temps long peut refléter un problème complexe plutôt qu'une mauvaise organisation du salarié.","question":"Quelle critique la représentante adresse-t-elle à l'indicateur utilisé ?","options":["La durée de connexion devrait être ajustée selon le nombre de dossiers, avant d'en examiner la difficulté","Le nombre de dossiers terminés serait un indicateur suffisant de la qualité du travail","La durée de présence devrait être interprétée avec la complexité des tâches accomplies","La difficulté des dossiers doit être estimée à partir des heures de présence seules"],"correct":"C","explanation":"C. Le temps en ligne ne révèle pas à lui seul les résultats ni la complexité des dossiers traités."},{"number":31,"points":26,"passage":"Les appels à la « passion du métier » peuvent soutenir l'engagement. Mais lorsqu'ils servent à justifier des heures non reconnues, ils masquent un déséquilibre. Un collectif de soignants défend la qualité du service tout en demandant des moyens et des horaires soutenables. Leur demande ne traduit pas un désintérêt pour leur travail. Les représentants proposent de discuter des effectifs et des interruptions qui ralentissent le service.","question":"Quelle opposition le collectif juge-t-il trompeuse ?","options":["Opposer le nombre d'interruptions aux temps de transmission entre collègues","Opposer l'engagement professionnel à des conditions de travail soutenables","Opposer les demandes de formation aux besoins de réorganisation des horaires","Opposer les contraintes des patients aux objectifs de continuité du service"],"correct":"B","explanation":"B. Les soignants défendent leur métier tout en demandant des heures reconnues, des effectifs et des horaires viables. Le collectif refuse donc de présenter la vocation professionnelle comme opposée aux conditions soutenables. Les autres oppositions ne sont pas celles discutées dans le passage."},{"number":32,"points":26,"passage":"Un diplôme décrit des acquis, mais ne résume pas toutes les aptitudes nécessaires dans une équipe. Un recruteur combine donc exercice technique, entretien et période d'observation rémunérée. Aucun de ces éléments n'est considéré comme infaillible. Leur intérêt vient du croisement des informations qu'ils apportent. Les observations seront discutées avec le candidat afin qu'il puisse préciser son raisonnement. Le cabinet veut éviter qu'une seule impression, favorable ou défavorable, décide de tout le recrutement sans possibilité de vérification.","question":"Quelle précaution structure la méthode de recrutement ?","options":["Confronter différentes observations pour limiter l'influence d'un critère isolé","Utiliser l'entretien comme mesure principale lorsque l'exercice technique diverge","Prendre la période d'observation comme confirmation suffisante du diplôme","Faire dépendre la sélection du jugement initial, puis expliquer les écarts"],"correct":"A","explanation":"A. Le recruteur croise exercices, entretiens et observation sans déclarer un seul indice suffisant."},{"number":33,"points":26,"passage":"La spécialisation rend certains services très efficaces, jusqu'au jour où une personne indispensable s'absente. Pour limiter ce risque, une entreprise organise des échanges de savoirs. Elle ne demande pas à chacun de tout maîtriser : elle veut que les collègues comprennent suffisamment les tâches voisines pour assurer une continuité. Les échanges se font pendant le temps de travail et portent d'abord sur les opérations fréquentes.","question":"Quel compromis permet de réduire la fragilité du service ?","options":["La spécialisation demeure, mais les collègues acquièrent des connaissances de relais","La polyvalence remplace progressivement les compétences propres à chaque poste","La documentation des tâches tient lieu de transmission entre salariés","La répartition des remplacements se fait uniquement selon l'ancienneté"],"correct":"A","explanation":"L'entreprise conserve la spécialisation tout en transmettant assez de savoir sur les tâches voisines pour pallier une absence."},{"number":34,"points":26,"passage":"Une formation courte promet des débouchés rapides. Des anciens stagiaires saluent la qualité des exercices, tout en signalant le manque de contacts avec les employeurs locaux. Ils distinguent l'apprentissage d'une technique de l'accès effectif à un emploi. Améliorer le second suppose un accompagnement que le seul contenu des cours ne remplace pas. Les stagiaires suggèrent des visites d'entreprises et des rencontres avec des recruteurs.","question":"Quel aspect de la promesse d'emploi est contesté ?","options":["La maîtrise d'une technique constitue le meilleur accès aux réseaux d'employeurs","Des rencontres avec les recruteurs peuvent remplacer la pratique en formation","L'apprentissage d'une compétence ne donne pas à lui seul accès au marché du travail","L'absence de contacts locaux signifie que les exercices sont insuffisants"],"correct":"C","explanation":"Une formation peut transmettre une technique sans créer les relations locales nécessaires à l'embauche. L'accompagnement vers l'emploi constitue une étape distincte."},{"number":35,"points":26,"passage":"Un service accorde aux équipes le choix de leurs méthodes, mais maintient des objectifs de sécurité communs. Cette autonomie exige de discuter les décisions et d'expliquer les écarts. Elle ne consiste donc pas à laisser chaque salarié agir sans règle. Les responsables doivent davantage accompagner et moins contrôler chaque geste. Des réunions courtes permettent de partager les solutions testées et de demander de l'aide.","question":"Comment la responsabilité des équipes est-elle redéfinie ?","options":["L'autonomie suppose que les résultats soient jugés sans examen des méthodes","Les équipes choisissent leurs règles de sécurité indépendamment des objectifs","Les managers ne doivent intervenir qu'en cas de désaccord avec un résultat","La liberté de choix reste liée à des exigences collectives explicites"],"correct":"D","explanation":"Les équipes choisissent leurs méthodes, mais doivent expliquer les décisions et respecter des objectifs de sécurité communs."},{"number":36,"points":33,"passage":"Le terme de compétence « transférable » laisse parfois croire qu'une aptitude passe sans effort d'un métier à un autre. Une organisatrice d'événements sait gérer des imprévus, mais doit apprendre les règles particulières du secteur hospitalier où elle souhaite travailler. Son expérience constitue un appui, pas une équivalence totale. Reconnaître les acquis et identifier ce qui reste à apprendre sont deux démarches complémentaires. Son accompagnatrice lui propose de décrire plusieurs situations de son ancien emploi et d'identifier ce qui peut être réutilisé. Elle devra ensuite découvrir les contraintes du soin, les responsabilités et les limites propres au nouveau poste. Ce travail évite deux erreurs opposées : prétendre qu'elle repart de zéro ou supposer que son expérience lui permet déjà de tout maîtriser. Les employeurs rencontrés apprécient cette manière de présenter à la fois des ressources et des besoins de formation.","question":"Que faut-il inférer de l'exemple de reconversion ?","options":["Adapter des compétences antérieures aux exigences et limites du nouveau secteur","Considérer les réussites passées comme des équivalences de qualification","Identifier les apprentissages manquants seulement après la prise du nouveau poste","Écarter les compétences déjà acquises pour préserver les règles du nouveau secteur"],"correct":"A","explanation":"A. Les capacités de gestion d'imprévus restent utiles mais doivent être réinterprétées dans le cadre spécifique des soins."},{"number":37,"points":33,"passage":"Un logiciel réduit le temps consacré aux tâches administratives. La direction veut utiliser tout le temps libéré pour augmenter le nombre de dossiers. Les salariés proposent d'en consacrer une partie à l'accueil des cas complexes, jusqu'alors traités trop vite. Ils ne contestent pas l'outil, mais la seule définition quantitative de son bénéfice. Un gain de temps peut améliorer la qualité du travail sans se traduire intégralement par une hausse du volume. La direction avait d'abord présenté le changement comme une manière évidente de traiter davantage de demandes avec les mêmes moyens. Les équipes ont apporté des exemples où quelques minutes supplémentaires éviteraient un rappel, une erreur ou une démarche inutile au client. Elles proposent de mesurer ces effets avant de fixer de nouveaux objectifs.","question":"Quel désaccord persiste malgré l'acceptation du logiciel ?","options":["Affecter le temps libéré aux seuls dossiers qui présentent un risque d'erreur","Déterminer le rendement du logiciel à partir du nombre de demandes en attente","Arbitrer entre accroître le volume et approfondir le traitement des cas difficiles","Réserver l'automatisation aux dossiers simples pour éliminer les suivis complexes"],"correct":"C","explanation":"C. La direction vise le volume; les salariés veulent consacrer une partie du gain à la qualité du suivi des cas complexes."},{"number":38,"points":33,"passage":"Dans un atelier, le meilleur réparateur devient responsable d'équipe. Il découvre que transmettre une consigne et résoudre un conflit demandent d'autres aptitudes que réparer une machine. L'entreprise avait considéré la promotion comme une récompense suffisante, sans prévoir de formation. L'expertise technique ne prépare pas automatiquement à l'accompagnement des personnes, même si elle peut en faciliter la compréhension du travail. Le salarié doit désormais distribuer les tâches, suivre les délais et accompagner des collègues dont les difficultés ne sont pas les siennes. Il continue parfois à reprendre les réparations lui-même, au risque de ne plus avoir de temps pour son nouveau rôle. Ses responsables organisent finalement un tutorat avec une personne d'un autre atelier. Ils souhaitent que la promotion reste une évolution choisie, et non une mise en difficulté présentée comme une récompense.","question":"Pourquoi la promotion du technicien ne suffit-elle pas ?","options":["La maîtrise d'un métier ne garantit pas les compétences nécessaires pour animer une équipe","La réparation doit rester la tâche principale d'un responsable récemment promu","La formation aux conflits peut être remplacée par un suivi plus strict des délais","Le tutorat doit servir à approfondir les gestes techniques plutôt que la gestion"],"correct":"A","explanation":"La promotion reconnaît les compétences techniques sans préparer à la répartition du travail, aux conflits et à l'accompagnement d'équipe."},{"number":39,"points":33,"passage":"Une organisation souhaite diversifier ses recrutements. Elle affiche cet objectif, puis conserve des entretiens à une heure inaccessible aux personnes déjà en poste et exige des stages non rémunérés. Une association souligne le décalage entre l'intention et les conditions concrètes. L'ouverture réelle du recrutement suppose de revoir les procédures qui excluent des candidats, même quand elles semblent ordinaires aux recruteurs. Elle propose des créneaux alternatifs et une épreuve courte réalisée sur des documents fictifs. Les recruteurs craignent de perdre un moyen de comparaison habituel, mais acceptent d'observer les résultats. Le groupe de travail vérifiera notamment quels profils peuvent aller au bout des démarches. Il ne s'agit pas d'abaisser les compétences attendues pour le poste : il s'agit d'éviter que des conditions sans rapport direct avec ces compétences servent de filtre.","question":"Sur quel type de changement repose une ouverture effective ?","options":["Réviser les seuils de compétences pour permettre davantage de candidatures","Maintenir des stages longs en donnant aux candidats plus de créneaux d'entretien","Diffuser l'objectif de diversité avant d'adapter les modalités de sélection","Modifier les contraintes de candidature sans abaisser les capacités recherchées"],"correct":"D","explanation":"D. Les modalités d'entretien et stages non rémunérés agissent comme des filtres sans rapport avec les qualifications."}]}$paper$::jsonb),
('tcf-reading-04','tcf-reading-2026-11-advanced-v5',$paper${"id":"tcf-reading-04","version":"tcf-reading-2026-11-advanced-v5","title":"TCF Reading · Test 04","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures.\n\nUne équipe sera présente dans le hall pour orienter les passagers. Les billets déjà achetés restent valables sur ce départ.","question":"Que doit vérifier le voyageur ?","options":["Le numéro de sa place","Un nouvel horaire","Le prix du billet","Le nouveau quai"],"correct":"D","explanation":"Le passage indique : « Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures. » Cela justifie la réponse : Le nouveau quai."},{"number":2,"points":3,"passage":"Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire.\n\nLe personnel a été informé de cette mesure et vous indiquera les espaces ouverts.","question":"Comment utiliser un billet acheté pour la veille ?","options":["Acheter un second billet","Demander un remboursement obligatoire","Le présenter directement à l'entrée","L'envoyer par courrier"],"correct":"C","explanation":"Le passage indique : « Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire. » Cela justifie la réponse : Le présenter directement à l'entrée."},{"number":3,"points":3,"passage":"La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin.\n\nElle ajoute quelques minutes au trajet mais reste praticable avec une remorque pour enfant.","question":"Quel itinéraire est proposé aux cyclistes ?","options":["Prendre un bateau obligatoire","Traverser la passerelle à vélo","Attendre le lendemain","Passer par le pont voisin"],"correct":"D","explanation":"Le passage indique : « La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin. » Cela justifie la réponse : Passer par le pont voisin."},{"number":4,"points":3,"passage":"Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques.\n\nLe service demande une description précise de l'objet et du trajet effectué. Une vérification sera faite avant toute restitution au propriétaire.","question":"Où chercher un bagage oublié ?","options":["Dans une consigne automatique","Au bureau de la gare","À l'arrêt du tramway","Dans le train suivant"],"correct":"B","explanation":"Le passage indique : « Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques. » Cela justifie la réponse : Au bureau de la gare."},{"number":5,"points":9,"passage":"Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé.\n\nJe préfère vérifier cette possibilité plutôt que changer deux fois la réservation et payer des frais inutiles.","question":"Pourquoi l'achat doit-il attendre ?","options":["Les billets sont tous gratuits","Le trajet est annulé définitivement","La durée du séjour reste incertaine","La famille refuse la visite"],"correct":"C","explanation":"Le passage indique : « Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé. » Cela justifie la réponse : La durée du séjour reste incertaine."},{"number":6,"points":9,"passage":"Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures.\n\nLes voyageurs doivent aussi libérer leur lit avant dix heures le jour du départ.","question":"Que doit apporter le client ?","options":["Un réfrigérateur","Des draps","Une serviette","Une clé de cuisine"],"correct":"C","explanation":"Le passage indique : « Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures. » Cela justifie la réponse : Une serviette."},{"number":7,"points":9,"passage":"Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas.\n\nJe pourrai dormir pendant le trajet et commencer ma visite après le petit déjeuner.","question":"Quel avantage motive ce choix ?","options":["Arriver en soirée","Voyager sans réservation","Économiser une nuit d'hébergement","Atteindre la vitesse maximale"],"correct":"C","explanation":"Le passage indique : « Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas. » Cela justifie la réponse : Économiser une nuit d'hébergement."},{"number":8,"points":9,"passage":"L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ.\n\nLes départs ont lieu devant l'office et durent environ une heure.","question":"Pourquoi faut-il s'inscrire ?","options":["La visite nécessite un passeport","Le nombre de participants est limité","L'entrée de la ville est payante","Le guide travaille uniquement en ligne"],"correct":"B","explanation":"Le passage indique : « L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ. » Cela justifie la réponse : Le nombre de participants est limité."},{"number":9,"points":9,"passage":"Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation.\n\nLes voyageurs sont invités à prévoir quelques minutes de marche supplémentaires depuis leur arrêt habituel.","question":"Quel effet le marché a-t-il sur le trajet ?","options":["Tous les arrêts deviennent payants","Le bus circule en sens inverse","Le lieu d'embarquement change","Le service cesse pour la journée"],"correct":"C","explanation":"Le passage indique : « Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation. » Cela justifie la réponse : Le lieu d'embarquement change."},{"number":10,"points":9,"passage":"Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel.\n\nLe magasin près de la gare garde les vélos réservés jusqu'à notre arrivée.","question":"Quelle contrainte veut-on éviter ?","options":["Réserver un hébergement","Transporter les vélos pendant les correspondances","Pédaler sur place","Acheter des boissons"],"correct":"B","explanation":"Le passage indique : « Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel. » Cela justifie la réponse : Transporter les vélos pendant les correspondances."},{"number":11,"points":15,"passage":"Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile.\n\nL'espace dispose de bancs et d'une prise pour recharger un téléphone. Les voyageurs ont demandé cet aménagement après plusieurs hivers passés à attendre sur un quai exposé au vent. L'agent mobile circulera surtout pendant les heures d'affluence, avec un appareil permettant de consulter les horaires et les tarifs. La municipalité souhaite conserver une présence utile dans la gare sans rouvrir exactement l'ancien service. Un bilan sera réalisé après les premiers mois pour vérifier les besoins.","question":"Quel service subsiste malgré la transformation ?","options":["Une aide humaine pour acheter un billet","La vente de repas chauds","La gratuité de tous les billets","Un guichet ouvert sans interruption"],"correct":"A","explanation":"Le passage indique : « Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile. » Cela justifie la réponse : Une aide humaine pour acheter un billet."},{"number":12,"points":15,"passage":"Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons.\n\nLes visites accompagnées devront désormais respecter un horaire et s'arrêter sur quelques emplacements plus larges. Les guides recevront une carte des zones sensibles afin de préparer leur parcours. La mairie souhaite maintenir les rencontres avec les commerçants, sans empêcher les résidents de sortir de chez eux.","question":"Pourquoi limiter les groupes ?","options":["Supprimer les visites culturelles","Réserver les rues aux voitures","Interdire tout tourisme","Faciliter la circulation dans les ruelles"],"correct":"D","explanation":"Le passage indique : « Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons. » Cela justifie la réponse : Faciliter la circulation dans les ruelles."},{"number":13,"points":15,"passage":"Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives.\n\nIl a repéré plusieurs villages accessibles sans voiture, ainsi qu'un sentier dont le départ se trouve près d'un arrêt. Les horaires de retour lui permettent de rester assez longtemps sur place. Il a aussi prévu une journée libre pour adapter son programme à la météo. La carte ne comprend pas les activités touristiques, mais il estime que la simplicité des déplacements lui sera déjà très utile.","question":"Pourquoi cette carte lui convient-elle ?","options":["Elle inclut un hôtel","Il ne prendra jamais le bus","Il prévoit plusieurs déplacements","Elle interdit les correspondances"],"correct":"C","explanation":"Le passage indique : « Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives. » Cela justifie la réponse : Il prévoit plusieurs déplacements."},{"number":14,"points":15,"passage":"Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués.\n\nLe parcours évite les rues les plus circulées et comporte plusieurs points de rassemblement clairement indiqués. Les accompagnateurs vérifient les présences avant de repartir, mais les parents restent responsables d'amener les enfants au bon endroit. L'école soutient l'essai pendant quelques semaines. Elle souhaite savoir si les familles peuvent s'organiser régulièrement, car une initiative agréable le premier jour ne devient pas automatiquement une solution fiable pour toute l'année.","question":"Qu'est-ce qu'un pédibus dans ce texte ?","options":["Un autocar touristique","Un prêt de bicyclettes","Un trajet à pied accompagné","Un cours de conduite"],"correct":"C","explanation":"Le passage indique : « Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués. » Cela justifie la réponse : Un trajet à pied accompagné."},{"number":15,"points":15,"passage":"Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas.\n\nLe responsable indique le menu prévu lors de la réservation et demande de signaler les besoins particuliers. Les quantités sont préparées selon le nombre annoncé, car il est difficile de se réapprovisionner rapidement à cette altitude. Le refuge préfère expliquer cette organisation avant l'arrivée plutôt que laisser croire qu'un repas supplémentaire peut toujours être improvisé à la fin d'une longue journée de marche.","question":"Pourquoi anticiper la réservation du dîner ?","options":["Réserver toutes les chambres","Éviter les frais de transport des clients","Adapter des provisions limitées","Permettre un service nocturne permanent"],"correct":"C","explanation":"Le passage indique : « Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas. » Cela justifie la réponse : Adapter des provisions limitées."},{"number":16,"points":15,"passage":"Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles.\n\nDes récits décrivent par exemple le travail au port, les jeux dans une ancienne cour et les commerces disparus. Les visiteurs suivent une carte et déclenchent les enregistrements devant les lieux concernés. Les témoignages sont présentés avec leur date et leur contexte. L'équipe ne veut pas remplacer toute recherche historique par des souvenirs : elle souhaite ajouter une perspective quotidienne à la découverte.","question":"Quelle particularité offre cette promenade ?","options":["La parole des habitants enrichit la visite","Les informations historiques sont interdites","Le visiteur doit devenir guide","Les monuments sont tous reconstruits"],"correct":"A","explanation":"Le passage indique : « Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles. » Cela justifie la réponse : La parole des habitants enrichit la visite."},{"number":17,"points":15,"passage":"Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus.\n\nCertaines personnes évoquent un manque de stationnement sûr à l'arrivée, d'autres un carrefour qui leur fait peur. Ces réponses ne demandent pas toutes le même investissement. Le service technique les comparera aux observations faites sur le terrain. La commune veut éviter de conclure trop vite qu'une piste peu fréquentée serait inutile ou que tous les habitants devraient simplement changer leurs habitudes.","question":"Pourquoi consulter les non-utilisateurs ?","options":["Les obliger à acheter un vélo","Comprendre ce qui freine l'usage","Fixer le prix des voitures","Remplacer les cyclistes dans l'enquête"],"correct":"B","explanation":"Le passage indique : « Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus. » Cela justifie la réponse : Comprendre ce qui freine l'usage."},{"number":18,"points":15,"passage":"Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures.\n\nLes sacs seront étiquetés et rangés dans une pièce fermée, accessible avec l'aide du personnel. Les voyageurs pourront ainsi poursuivre leur visite avant de rejoindre leur train. L'hôtel rappelle toutefois que les objets précieux doivent rester avec leurs propriétaires. Il souhaite rendre ce service pratique sans créer de confusion sur l'heure de départ.","question":"Quelle distinction faut-il faire ?","options":["Les chambres deviennent des consignes publiques","Les sacs doivent quitter l'hôtel à onze heures","Le dépôt inclut une nouvelle nuit","Déposer ses sacs ne permet pas de garder sa chambre"],"correct":"D","explanation":"Le passage indique : « Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures. » Cela justifie la réponse : Déposer ses sacs ne permet pas de garder sa chambre."},{"number":19,"points":15,"passage":"La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale.\n\nLes enfants ont participé au choix des dessins, après avoir essayé plusieurs versions dans une station témoin. Les adultes peuvent également utiliser ces repères lorsqu'ils découvrent le réseau. Les noms des lignes et les règles de sécurité restent communs à tous ; l'objectif est d'ajouter une manière de lire l'espace, sans créer deux réseaux d'informations contradictoires.","question":"Quel objectif est poursuivi ?","options":["Rendre l'orientation plus accessible aux jeunes","Réserver les stations aux familles","Augmenter le nombre de correspondances","Supprimer les noms des lignes"],"correct":"A","explanation":"Le passage indique : « La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale. » Cela justifie la réponse : Rendre l'orientation plus accessible aux jeunes."},{"number":20,"points":21,"passage":"Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison. Les habitants espèrent aussi que cette répartition limitera les files devant les petites attractions de l'île. Des informations seront recueillies auprès des visiteurs ayant choisi chaque départ. Les responsables veulent notamment vérifier si le nouveau service permet des séjours plus agréables ou déplace simplement l'affluence vers une autre heure, sans résoudre les difficultés signalées.","question":"Quelle prudence accompagne le premier bilan ?","options":["Attendre une observation plus longue","Conclure à une baisse certaine des visiteurs","Fermer les commerces le matin","Supprimer immédiatement le second bateau"],"correct":"A","explanation":"Le passage indique : « Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison. » Cela justifie la réponse : Attendre une observation plus longue."},{"number":21,"points":21,"passage":"Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes. Elle compare donc la durée entre les lieux de travail, plutôt qu'entre deux points de départ seulement. Les salariés doivent préciser les correspondances nécessaires et les possibilités de travailler pendant le trajet. Cette méthode n'impose pas une solution identique dans chaque cas, mais rend la décision moins dépendante d'une différence de tarif isolée.","question":"Quelle comparaison pratique-t-elle ?","options":["Elle exclut tout temps d'attente","Elle compare uniquement les repas","Elle retient seulement le prix affiché","Elle considère le trajet dans son ensemble"],"correct":"D","explanation":"Le passage indique : « Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes. » Cela justifie la réponse : Elle considère le trajet dans son ensemble."},{"number":22,"points":21,"passage":"Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production. Les petits groupes sont prévenus que les horaires peuvent changer et qu'ils ne verront pas toujours la même étape de fabrication. L'artisan préfère expliquer un travail réel plutôt que répéter une démonstration à la demande. L'office de tourisme accepte cette souplesse et propose d'autres visites lorsque l'atelier doit se concentrer sur sa production.","question":"Quel principe organise ces visites ?","options":["Respecter l'activité principale de l'atelier","Garantir une ouverture touristique permanente","Transformer toutes les commandes en visites","Remplacer le métier par des spectacles"],"correct":"A","explanation":"Le passage indique : « Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production. » Cela justifie la réponse : Respecter l'activité principale de l'atelier."},{"number":23,"points":21,"passage":"Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique. La commune avait conçu l'offre pour réduire les trajets automobiles des vacanciers, mais les associations locales estiment que les besoins permanents ne doivent pas être oubliés. Les responsables souhaitent trouver un financement stable avant d'étendre la gratuité, afin de ne pas annoncer un droit qui disparaîtrait après une seule saison.","question":"Que revendiquent les habitants ?","options":["Un traitement équitable pour les trajets locaux","Une priorité pour les touristes étrangers","Le rétablissement des embouteillages","La fermeture des hébergements"],"correct":"A","explanation":"Le passage indique : « Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique. » Cela justifie la réponse : Un traitement équitable pour les trajets locaux."},{"number":24,"points":21,"passage":"Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule. Les utilisateurs ont notamment besoin de savoir si un passage comporte des marches ou un trottoir difficile. La voyageuse demande que ces informations apparaissent avant le choix du trajet. Elle souhaite pouvoir décider elle-même du compromis acceptable entre durée et effort, plutôt que recevoir un itinéraire présenté comme idéal sur un seul critère.","question":"Quelle limite de l'application est montrée ?","options":["La poussette empêche tout déplacement","Tous les itinéraires sont trop longs","Les escaliers accélèrent chaque trajet","La rapidité ne garantit pas l'accessibilité"],"correct":"D","explanation":"Le passage indique : « Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule. » Cela justifie la réponse : La rapidité ne garantit pas l'accessibilité."},{"number":25,"points":21,"passage":"Un village réduit le stationnement au centre et ouvre un parking extérieur relié à pied. Les recettes du stationnement financent l'entretien du chemin. La mesure associe donc limitation de la voiture et amélioration de l'accès final. Les premiers visiteurs se plaignent d'une marche plus longue, mais les riverains constatent moins de circulation devant les commerces. La mairie prévoit de mieux signaler le parcours et d'y ajouter des bancs.","question":"Quel usage des recettes accompagne la restriction automobile ?","options":["Réduire la durée de stationnement au centre pour financer la signalétique touristique","Utiliser les recettes du stationnement pour rendre praticable le trajet à pied","Accroître les recettes du parking extérieur avant d'élargir les accès routiers","Compenser les commerces du centre pour les trajets supplémentaires des visiteurs"],"correct":"B","explanation":"Les recettes du parking extérieur financent le chemin qui rejoint le centre. La limitation de la voiture s'accompagne ainsi d'un accès piéton praticable."},{"number":26,"points":21,"passage":"Une famille choisit deux étapes longues plutôt que sept villes en dix jours. Elle renonce à plusieurs sites célèbres, mais souhaite disposer de temps pour improviser et connaître la vie quotidienne sur place. La famille prévoit de cuisiner quelques repas et d'utiliser les transports locaux. Elle estime qu'un programme moins chargé permet aussi de réagir à une rencontre ou à une recommandation reçue sur place, plutôt que suivre constamment des réservations préparées à l'avance.","question":"Quelle valeur les voyageurs privilégient-ils dans leur programme ?","options":["Préférer une exploration approfondie qui laisse place à l'imprévu","Maximiser les rencontres tout en conservant les réservations prévues","Choisir les sites célèbres selon la durée des déplacements disponibles","Consacrer moins de temps aux étapes pour essayer davantage de transports"],"correct":"A","explanation":"La famille préfère deux étapes longues pour disposer de temps libre et découvrir le quotidien. Le texte oppose cette souplesse à un programme multipliant les villes."},{"number":27,"points":21,"passage":"Un organisateur de sorties invite les participants à indiquer leurs besoins avant de s'inscrire. Il précise ce qui peut être adapté et ce qui ne peut pas l'être. Cette transparence évite de confondre accueil bienveillant et accessibilité réellement assurée. Les participants peuvent ensuite discuter d'une aide éventuelle avec l'organisateur. Certaines sorties seront adaptées, tandis que d'autres demanderont un autre parcours ou un accompagnement différent.","question":"Pourquoi l'organisateur détaille-t-il les limites des adaptations ?","options":["Limiter l'inscription aux sorties où aucune adaptation ne paraît nécessaire","Accorder l'aide demandée sans préciser les conditions matérielles du parcours","Indiquer les possibilités après inscription afin de réduire les renoncements","Permettre une décision informée en distinguant accueil et accessibilité réelle"],"correct":"D","explanation":"L'organisateur explique les adaptations possibles et leurs limites pour que chacun juge si une sortie répond à ses besoins avant l'inscription."},{"number":28,"points":21,"passage":"Une ligne rurale de bus semblait peu utilisée d'après les validations électroniques. Une enquête a révélé que plusieurs abonnements n'exigeaient pas de validation. Le comptage devait être corrigé avant de décider une suppression. Des comptages manuels ont été organisés sur plusieurs jours pour compléter les données. L'association d'usagers insiste pour que la décision ne repose pas uniquement sur un chiffre dont le mode de production était mal compris, alors que le service reste important pour des habitants sans voiture.","question":"Quelle limite méthodologique remettait la décision en cause ?","options":["La validation électronique mesure surtout la régularité des abonnements","Certains trajets n'apparaissaient pas dans l'indicateur utilisé","Les relevés manuels surestimaient les voyageurs sans abonnement","Les validations reflétaient mal les déplacements lors des jours de pointe"],"correct":"B","explanation":"Certains abonnements ne nécessitent pas de validation ; le comptage électronique a donc sous-estimé l'usage de la ligne."},{"number":29,"points":21,"passage":"Une destination met en avant des séjours hors saison. Certains professionnels craignent des recettes plus faibles par semaine ; d'autres espèrent une activité moins concentrée et des emplois plus stables. Les hébergeurs soulignent cependant que l'ouverture prolongée demande du personnel, du chauffage et des services de transport. Le programme devra donc coordonner plusieurs acteurs, plutôt que compter sur une simple campagne de communication.","question":"Quelle possibilité motive le développement des séjours hors saison ?","options":["Concentrer les séjours sur quelques semaines pour conserver le personnel permanent","Élargir la période d'activité afin de répartir les recettes et les emplois","Adapter les transports aux périodes où les hébergeurs sont habituellement fermés","Remplacer une partie des visiteurs d'été par des séjours de plus courte durée"],"correct":"B","explanation":"Les séjours hors saison pourraient étaler l'activité et stabiliser les emplois ; cela suppose toutefois une coordination de l'hébergement, des transports et du personnel."},{"number":30,"points":26,"passage":"Les classements touristiques comptent souvent les arrivées. Une commune préfère également regarder la durée des séjours et les dépenses réalisées auprès des entreprises locales. Un passage très bref peut encombrer le centre sans soutenir beaucoup son économie. Elle recueille ces informations auprès des hébergements et des commerçants, sans demander aux visiteurs de détailler toutes leurs dépenses. Elle veut mieux comprendre ce que la fréquentation apporte réellement à la vie économique de la commune.","question":"Pourquoi la commune juge-t-elle les arrivées insuffisantes pour évaluer le tourisme ?","options":["La fréquentation ne renseigne pas seule sur les dépenses et la durée des séjours","La durée des séjours permettrait à elle seule d'estimer la totalité des retombées","Les passages comptés devraient être remplacés par des enquêtes auprès des visiteurs","Les dépenses locales peuvent être évaluées indépendamment des hébergements"],"correct":"A","explanation":"A. Les arrivées ne permettent pas de déduire les retombées réelles sans durée des séjours et dépenses locales."},{"number":31,"points":26,"passage":"Un billet unique facilite les correspondances entre deux réseaux. Pourtant, les horaires restent mal coordonnés. Les voyageurs gagnent en simplicité d'achat, mais continuent à perdre du temps à attendre. L'intégration tarifaire représente une étape, pas une solution complète. Les deux réseaux préparent maintenant leurs changements ensemble. Les voyageurs demandent notamment des correspondances possibles le soir, car un billet pratique perd beaucoup de son intérêt lorsque le dernier véhicule part avant l'arrivée du premier.","question":"Quelle amélioration manque encore malgré l'accord tarifaire ?","options":["Synchroniser davantage les horaires des réseaux, surtout lors des derniers trajets","Ajouter un billet commun pour les trajets qui dépassent les horaires réguliers","Réduire le temps consacré à la validation de titres avant chaque correspondance","Proposer des informations de prix plus précises aux nouveaux abonnés"],"correct":"A","explanation":"Le billet unique simplifie l'achat, mais les horaires mal raccordés maintiennent de longues attentes. L'intégration tarifaire ne résout pas la correspondance."},{"number":32,"points":26,"passage":"Le terme de voyage « authentique » est parfois utilisé pour vendre une expérience préparée à l'avance. Cela ne la rend pas nécessairement sans intérêt. La difficulté apparaît lorsque les visiteurs croient découvrir une vie quotidienne spontanée alors qu'ils assistent à une mise en scène conçue pour eux. Les visiteurs sauront alors ce qu'ils découvrent et pourront poser des questions sur la vie du lieu au-delà de la scène présentée.","question":"Quelle ambiguïté le terme « authentique » peut-il créer ?","options":["Une expérience présentée comme spontanée peut être organisée pour les touristes","Une mise en scène perd tout intérêt lorsqu'elle est annoncée aux visiteurs","La participation des habitants garantirait l'authenticité de toute visite","Une visite préparée serait plus fidèle si elle durait plusieurs journées"],"correct":"A","explanation":"Une visite mise en scène peut présenter un intérêt ; le problème apparaît lorsqu'elle est vendue ou perçue comme une découverte spontanée du quotidien."},{"number":33,"points":26,"passage":"Installer une piste cyclable sur un axe isolé améliore un segment du trajet. Si elle s'arrête avant un carrefour dangereux, certaines personnes continueront à éviter le vélo. Pour elles, la sécurité du parcours dépend de son point le plus difficile, et non de sa seule longueur aménagée. Les associations demandent donc de regarder les ruptures du réseau et les lieux d'arrivée.","question":"Quel critère de sécurité ne peut être résumé à la longueur aménagée ?","options":["Adapter la capacité des sections existantes avant de modifier les carrefours","Traiter les ruptures de l'itinéraire pour sécuriser le parcours dans son ensemble","Privilégier la longueur totale des voies utilisées par les cyclistes réguliers","Concentrer les travaux sur les axes dont les derniers mètres sont déjà sûrs"],"correct":"B","explanation":"Une piste s'arrêtant avant un carrefour dangereux n'assure pas un trajet sûr. La continuité jusqu'à l'arrivée compte davantage que la seule longueur aménagée."},{"number":34,"points":26,"passage":"Une ville historique fait payer l'accès à un belvédère pour financer sa restauration. Le débat ne porte pas seulement sur le tarif : certains habitants souhaitent pouvoir continuer à fréquenter un lieu qui appartenait à leurs promenades ordinaires. La conservation soulève ainsi une question d'usage local. La commune étudie plusieurs formules, dont un accès gratuit certains jours pour les résidents.","question":"Quel intérêt doit être concilié avec les recettes de restauration ?","options":["La restauration doit être financée par des tarifs fixés selon la fréquentation","L'accès habituel des résidents doit être pris en compte dans le financement","La gratuité des visites devrait dépendre de l'état d'avancement des travaux","Les billets payants devraient être limités aux visiteurs venus hors saison"],"correct":"B","explanation":"Le tarif de restauration est discuté avec l'accès des résidents à un lieu de promenade familier. La commune envisage des jours gratuits pour eux."},{"number":35,"points":26,"passage":"Des stations indiquent le temps moyen de correspondance. Une association demande d'ajouter une marge pour les personnes se déplaçant lentement. Une moyenne peut être exacte pour l'ensemble des voyageurs et néanmoins trompeuse pour une partie d'entre eux. L'information doit permettre d'anticiper cette variation. L'association ne demande pas que tous les trajets deviennent plus lents, mais que chacun puisse anticiper une correspondance réalisable avec ses capacités et ses bagages.","question":"Quelle information supplémentaire rendrait l'affichage plus utile ?","options":["Afficher des durées plus rapides pour les voyageurs sans bagages","Ajouter une marge identique à chaque correspondance sur le réseau","Présenter des durées adaptées à des vitesses de déplacement différentes","Calculer les moyennes à partir des seuls trajets les plus longs"],"correct":"C","explanation":"Une moyenne correcte peut ne pas convenir à une personne qui se déplace lentement. L'association veut rendre visible cette variation pour anticiper une correspondance possible."},{"number":36,"points":33,"passage":"Une métropole vante une nouvelle liaison rapide avec son aéroport. Les affiches annoncent quinze minutes de trajet. Pour beaucoup d'usagers, il faut toutefois rejoindre la gare de départ, attendre le train puis parcourir les terminaux. Le chiffre annoncé reste exact entre deux points précis. Il devient trompeur lorsqu'il est compris comme la durée totale du déplacement. Les voyageurs qui connaissent déjà la liaison interprètent souvent correctement l'annonce. Ceux qui viennent pour la première fois peuvent au contraire organiser une correspondance trop courte. Une association propose d'afficher séparément le temps dans le train et des exemples de trajets complets depuis plusieurs quartiers. Le débat porte ainsi sur ce que l'on choisit de mesurer pour informer utilement, et sur l'écart entre une formule publicitaire vraie dans un cadre limité et l'expérience de ceux qui l'utilisent pour décider.","question":"Pourquoi les quinze minutes annoncées peuvent-elles induire en erreur ?","options":["Le chiffre inclut l'accès au train mais non la traversée des terminaux","Le temps mesuré entre deux gares ne décrit pas nécessairement le trajet complet","La durée varie avant tout selon les écarts de ponctualité des trains","Les nouveaux voyageurs interprètent le temps affiché comme une fréquence de passage"],"correct":"B","explanation":"B. Quinze minutes désigne le seul segment ferroviaire, non l'accès initial, l'attente ni les terminaux."},{"number":37,"points":33,"passage":"Une région encourage le tourisme à vélo. Elle finance des itinéraires, mais plusieurs hébergements refusent encore les séjours d'une seule nuit. Les cyclistes qui avancent chaque jour doivent alors s'éloigner de leur parcours ou modifier leurs étapes. Le développement d'un mode de voyage suppose une cohérence entre l'infrastructure et les services qui permettent effectivement de l'utiliser. Les hébergeurs expliquent que l'accueil d'une nuit demande presque autant de préparation qu'un séjour plus long. La région cherche donc des solutions de réservation et de bagagerie qui rendent cette clientèle plus facile à recevoir. Des voyageurs seront invités à tester le parcours complet avant une nouvelle campagne de promotion. Les élus souhaitent éviter de présenter les pistes comme une offre déjà suffisante, alors que les étapes demeurent difficiles à organiser.","question":"Quelle adaptation conditionne l'essor de l'itinérance cycliste ?","options":["Organiser les réservations de façon groupée pour les cyclistes arrivant le même jour","Favoriser des séjours plus longs pour diminuer la charge des hébergeurs","Proposer des nuitées qui permettent de progresser par étapes sans détour","Augmenter les itinéraires balisés avant de revoir les conditions d'accueil"],"correct":"C","explanation":"Les itinéraires cyclables financés restent difficiles à utiliser lorsque les hébergements refusent les nuitées courtes nécessaires aux étapes."},{"number":38,"points":33,"passage":"Un parc naturel limite les réservations estivales pour préserver certains sites. Des prestataires proposent en réponse des horaires très matinaux, hors du créneau réglementé. La fréquentation totale risque de rester inchangée, avec davantage de perturbations pour la faune. Une règle évaluée uniquement sur ses créneaux officiels peut déplacer la pression plutôt que la diminuer. Les gestionnaires vont donc observer l'ensemble de la journée, y compris les départs proposés hors des périodes habituelles. Les professionnels demandent des règles lisibles et applicables à tous, afin que certains ne profitent pas simplement d'un vide dans le calendrier. Le parc souhaite préserver la possibilité de découverte tout en diminuant la pression réelle. Il devra examiner les déplacements des visiteurs, mais aussi les moments où les animaux peuvent rester tranquilles. Cette expérience rappelle qu'une mesure apparemment respectée peut manquer son objectif si les comportements s'organisent autour de ses limites.","question":"Quel effet indirect la restriction des créneaux peut-elle produire ?","options":["La baisse des départs au lever du jour pourrait concentrer les groupes pendant les heures réglementées","Les professionnels pourraient reporter les séjours vers des zones déjà ouvertes au public","Les interdictions pourraient réduire les réservations sans diminuer le temps de présence des guides","La limitation des créneaux officiels peut conduire à déplacer les visiteurs vers d'autres heures"],"correct":"D","explanation":"D. L'offre de départs matinaux hors créneaux peut déplacer la pression sur la faune sans abaisser l'affluence totale."},{"number":39,"points":33,"passage":"Les voyageurs souhaitent souvent être guidés vers des lieux moins fréquentés. Mais lorsqu'une plateforme recommande simultanément la même petite place à des milliers de personnes, elle transforme ce lieu discret en nouvelle attraction. Les informations qui dispersent individuellement les parcours peuvent ainsi concentrer collectivement les visiteurs. La gestion des flux exige d'observer les effets d'ensemble des recommandations, pas seulement leur utilité pour chaque utilisateur. Les habitants de ces nouveaux lieux peuvent alors subir une augmentation rapide du bruit et des passages, sans avoir été consultés. La plateforme envisage de varier ses suggestions et de travailler avec les responsables locaux. Elle souhaite conserver des conseils utiles sans transformer systématiquement chaque découverte en destination incontournable. Les spécialistes soulignent toutefois qu'une recommandation moins précise peut aussi être moins pratique pour le voyageur.","question":"Quel effet collectif peut contredire l'intention des recommandations ?","options":["Des recommandations plus variées peuvent rendre les visites moins prévisibles","La concentration des visites suppose que les voyageurs partagent la même heure de départ","Un détour conseillé individuellement n'affecte les quartiers que si le site est célèbre","Des choix identiques proposés à grande échelle peuvent créer un nouveau lieu surfréquenté"],"correct":"D","explanation":"D. Une plateforme peut concentrer collectivement ses utilisateurs sur un même lieu discret en le recommandant massivement."}]}$paper$::jsonb),
('tcf-reading-05','tcf-reading-2026-11-advanced-v5',$paper${"id":"tcf-reading-05","version":"tcf-reading-2026-11-advanced-v5","title":"TCF Reading · Test 05","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin.\n\nUn agent peut expliquer les autres points de collecte. Merci de ne rien laisser à côté de la boîte.","question":"Où déposer les piles ?","options":["Dans le magasin prévu pour les ampoules","À côté de la boîte de collecte","Dans le bac des déchets en papier","Dans la boîte située à l'accueil"],"correct":"D","explanation":"Le passage indique : « Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin. » Cela justifie la réponse : À l'accueil."},{"number":2,"points":3,"passage":"La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie.\n\nLes distributions de sacs se font aux horaires habituels.","question":"Quel contenant faut-il utiliser ?","options":["Les sacs en papier remis par la mairie","Les sacs compostables du commerce","Les sacs plastiques de collecte","Les grands sacs de déchets ménagers"],"correct":"A","explanation":"Le passage indique : « La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie. » Cela justifie la réponse : Un sac en papier."},{"number":3,"points":3,"passage":"En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures.\n\nDes contrôles auront lieu pendant toute la période annoncée par la commune.","question":"Quel arrosage reste permis ?","options":["Arroser les jeunes arbres avant huit heures","Arroser les jeunes arbres en journée","Arroser les pelouses tôt le matin","Arroser les pelouses après le coucher du soleil"],"correct":"A","explanation":"Le passage indique : « En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures. » Cela justifie la réponse : Celui des jeunes arbres tôt le matin."},{"number":4,"points":3,"passage":"Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire.\n\nL'équipe souhaite réduire les petits déchets emportés après chaque vente. Cette organisation sera évaluée avec les clients au cours du mois prochain.","question":"Quelle nouvelle habitude est proposée ?","options":["Utiliser des tasses fournies par le café","Rapporter les couvercles après usage","Apporter une tasse à faire laver sur place","Apporter sa tasse réutilisable propre"],"correct":"D","explanation":"Le passage indique : « Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire. » Cela justifie la réponse : Utiliser sa propre tasse propre."},{"number":5,"points":9,"passage":"Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles.\n\nNous pourrons tout rapporter après le repas au lieu de remplir les poubelles du parc. J'ai aussi prévu des couverts que nous laverons chez moi.","question":"Que cherche à limiter ce message ?","options":["Réduire les portions servies au pique-nique","Éviter de transporter des boissons chaudes","Réduire le nombre de plats préparés","Limiter les contenants à usage unique"],"correct":"D","explanation":"Le passage indique : « Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles. » Cela justifie la réponse : Les contenants jetables."},{"number":6,"points":9,"passage":"L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire.\n\nUn bénévole examinera d'abord l'objet pour vérifier si l'intervention est possible. Les réparations complexes seront orientées vers un professionnel du secteur.","question":"Pourquoi certains appareils sont-ils refusés ?","options":["Les bénévoles ne sont pas habilités à intervenir sur le gaz","Les réparations de ces appareils demandent plus de temps","La collecte des pièces de rechange est trop coûteuse","L'atelier réserve leur réparation aux séances du soir"],"correct":"A","explanation":"Le passage indique : « L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire. » Cela justifie la réponse : Pour respecter les compétences disponibles."},{"number":7,"points":9,"passage":"Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon.\n\nCe sera intéressant de voir quelles plantes apparaissent et si les insectes reviennent. Je prendrai quelques photographies pour comparer les changements au fil de la saison.","question":"Comment le jardin sera-t-il entretenu ?","options":["Le passage vers le cabanon restera non tondu","La tonte aura lieu uniquement en fin de saison","Une partie du jardin restera sans tonte","Les plantes spontanées seront retirées avant l'été"],"correct":"C","explanation":"Le passage indique : « Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon. » Cela justifie la réponse : Avec des zones volontairement non tondues."},{"number":8,"points":9,"passage":"La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité.\n\nLes groupes seront accompagnés dans les zones autorisées.","question":"Quelle condition concerne les enfants ?","options":["Participer uniquement avec un groupe scolaire","Venir accompagné même avant huit ans","Avoir suivi une initiation au tri sélectif","Avoir au moins huit ans pour la visite"],"correct":"D","explanation":"Le passage indique : « La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité. » Cela justifie la réponse : Avoir au moins huit ans."},{"number":9,"points":9,"passage":"Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels.\n\nLe point de retour se trouve près de la sortie principale.","question":"Que faut-il faire pour récupérer la somme déposée ?","options":["Rapporter le gobelet après la fermeture","Rapporter le gobelet avant la fermeture","Remettre le gobelet à l'entrée du site","Rendre le gobelet lors d'un autre festival"],"correct":"B","explanation":"Le passage indique : « Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels. » Cela justifie la réponse : Rapporter le gobelet à temps."},{"number":10,"points":9,"passage":"Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires.\n\nLes participants présenteront leurs choix au jury. Des photographies prises à différentes périodes permettront aussi d'expliquer l'évolution du jardin et les difficultés rencontrées.","question":"Quel critère est privilégié ?","options":["La variété des végétaux présentés","Une utilisation économe de l'eau","Le caractère rare des fleurs","La qualité des photographies du jardin"],"correct":"B","explanation":"Le passage indique : « Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires. » Cela justifie la réponse : La gestion de l'eau."},{"number":11,"points":15,"passage":"Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis.\n\nLe personnel retire ensuite ce poids du montant utilisé pour calculer le prix. Une démonstration est proposée aux nouveaux clients, car plusieurs personnes hésitent à se servir seules lors de leur première visite. Le magasin accepte des boîtes de tailles différentes, à condition qu'elles soient propres et adaptées au produit choisi. Il souhaite rendre cette formule simple sans promettre que tous les aliments pourront être transportés dans n'importe quel récipient. Les tarifs restent affichés au même endroit.","question":"Pourquoi pèse-t-on le contenant vide ?","options":["Pour fixer le prix de chaque bocal","Pour vérifier la capacité du récipient","Pour déduire le poids du récipient du prix","Pour contrôler la quantité de produit admise"],"correct":"C","explanation":"Le passage indique : « Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis. » Cela justifie la réponse : Pour ne facturer que le produit."},{"number":12,"points":15,"passage":"Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables.\n\nLes élèves notent la météo et le nombre de personnes présentes, afin de conserver une trace des circonstances. Une association vérifie les espèces difficiles à identifier sur les photographies. L'école veut surtout apprendre à observer avec régularité, plutôt qu'annoncer un résultat spectaculaire après une seule séance.","question":"Pourquoi répéter les mêmes conditions ?","options":["Pour observer un plus grand nombre d'espèces","Pour éviter de consigner les conditions météo","Pour répartir les élèves dans différents lieux","Pour rendre les résultats comparables"],"correct":"D","explanation":"Le passage indique : « Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables. » Cela justifie la réponse : Faciliter la comparaison des observations."},{"number":13,"points":15,"passage":"Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture.\n\nLes erreurs concernaient notamment les emballages et les restes trop volumineux. L'association installera des indications illustrées à proximité du bac et désignera des personnes de contact dans plusieurs immeubles. Les usagers pourront leur poser une question avant de déposer un produit inhabituel. Le comité souhaite que cette interruption serve à améliorer le fonctionnement, sans faire croire qu'un composteur se gère tout seul. Un premier contrôle sera organisé quelques semaines après la reprise.","question":"Quel problème la démonstration doit-elle résoudre ?","options":["Le choix du lieu d'installation du composteur","La récupération des emballages en bon état","Les dépôts de matières inadaptées au compostage","Le transport des déchets vers la déchèterie"],"correct":"C","explanation":"Le passage indique : « Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture. » Cela justifie la réponse : Les erreurs de dépôt."},{"number":14,"points":15,"passage":"La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année.\n\nLes plantations ont été choisies avec une pépinière et une association naturaliste. Certaines fleurissent au printemps, d'autres portent des fruits plus tard. Le calendrier d'entretien tiendra compte des périodes où les animaux utilisent les branches pour se reproduire. Les agents expliquent aux riverains que la haie pourra paraître moins uniforme sans être abandonnée. Une petite visite permettra de découvrir les espèces installées et de comprendre les fonctions recherchées, au-delà de leur seul aspect décoratif.","question":"Quel objectif guide ce remplacement ?","options":["Offrir des habitats à davantage d'espèces","Rendre toutes les haies identiques toute l'année","Réduire le nombre de plantes locales utilisées","Faciliter une taille uniforme à chaque saison"],"correct":"A","explanation":"Le passage indique : « La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année. » Cela justifie la réponse : Favoriser la diversité du vivant."},{"number":15,"points":15,"passage":"Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres.\n\nDes bénévoles vérifient l'état des vêtements avant de les orienter vers les associations partenaires. Une petite couture ou un bouton remplacé permet parfois de remettre rapidement un article en circulation. Les tissus vraiment usés seront regroupés pour un autre traitement. Le magasin souhaite éviter que l'ensemble des dons soit considéré comme une matière indistincte. Il indiquera les résultats de la collecte pour expliquer les volumes réutilisés et ceux qui nécessitent une transformation plus importante.","question":"Pourquoi distinguer les deux catégories ?","options":["Envoyer les tissus encore utilisables au recyclage","Répartir les articles selon le prix d'origine","Conserver la possibilité de réemployer certains vêtements","Écarter les vêtements qui demandent une petite couture"],"correct":"C","explanation":"Le passage indique : « Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres. » Cela justifie la réponse : Préserver la possibilité de réutilisation."},{"number":16,"points":15,"passage":"Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs.\n\nLes organisateurs ont préparé un parcours et expliqué les zones à éviter avant le départ. Les sacs seront transportés par les passages déjà fréquentés. Si un déchet se trouve dans un endroit sensible, un responsable décidera comment intervenir plus tard. Les bénévoles comprennent ainsi qu'une action de nettoyage ne se juge pas seulement au nombre de sacs remplis.","question":"Quelle précaution est prise ?","options":["Nettoyer uniquement les berges déjà dégradées","Éviter de perturber les refuges des oiseaux nicheurs","Retirer les plantes aquatiques avant les déchets","Déplacer les nids avant d'accéder aux roselières"],"correct":"B","explanation":"Le passage indique : « Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs. » Cela justifie la réponse : Éviter certains habitats pendant le nettoyage."},{"number":17,"points":15,"passage":"Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel.\n\nLes familles comparent des périodes de durée semblable et indiquent les changements de leurs habitudes. Un week-end avec des invités ou une longue absence peut peser sur le résultat. L'association les aide à lire les relevés sans transformer l'expérience en compétition. Elle veut savoir si l'équipement contribue à réduire la consommation dans des conditions ordinaires. Les participants discuteront ensuite des solutions les plus simples à conserver au quotidien, avec ou sans nouvelle installation.","question":"Que veulent-ils éviter ?","options":["Une erreur dans le prix des équipements installés","Attribuer trop vite les variations aux mousseurs","La comparaison de périodes de durée semblable","Le relevé du nombre de personnes dans le foyer"],"correct":"B","explanation":"Le passage indique : « Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel. » Cela justifie la réponse : Une interprétation trop rapide des chiffres."},{"number":18,"points":15,"passage":"Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée.\n\nLes lots sont comptés avant chaque retour afin de repérer rapidement une pièce manquante. L'entreprise vérifie aussi que le nettoyage correspond au type de vaisselle proposé. Une fiche explique les horaires et les modalités de transport. Le responsable suivra les quantités réellement réutilisées au cours de la saison, ainsi que les déplacements nécessaires pour assurer les prêts, avant de dresser un bilan plus large.","question":"Quel service est inclus ?","options":["Le nettoyage des pièces après leur retour","La préparation des repas avant la réception","Le dressage des tables pour les invités","La livraison des boissons avec la vaisselle"],"correct":"A","explanation":"Le passage indique : « Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée. » Cela justifie la réponse : Le nettoyage après retour."},{"number":19,"points":15,"passage":"Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux.\n\nUn guide rappelle les limites du parcours et les points de rendez-vous en cas de séparation du groupe. Les zones difficiles d'accès resteront exclues, même si des déchets y sont visibles. Les participants sont invités à porter des chaussures fermées et à ne pas ramasser les objets dangereux à mains nues.","question":"Pourquoi choisir ce moment ?","options":["Pour profiter d'une plage plus accessible au public","Pour limiter le risque lié à la montée des eaux","Pour observer davantage de déchets dans l'eau","Pour prolonger la collecte jusqu'à la marée suivante"],"correct":"B","explanation":"Le passage indique : « Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux. » Cela justifie la réponse : Réduire un risque pour les participants."},{"number":20,"points":21,"passage":"Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. Les clients recevront des indications de conservation et pourront acheter une petite quantité seulement. Le magasin souhaite écouler les produits encore utilisables, pas transformer l'urgence de la vente en prétexte à remplir inutilement les paniers. L'association propose de comparer les achats avec les besoins prévus pour les repas. Une réduction importante ne constitue une économie que si les aliments sont consommés dans les conditions nécessaires.","question":"Quelle limite accompagne la promotion ?","options":["Réserver les réductions aux achats en grande quantité","Promouvoir les produits dont la date est éloignée","Éviter que le gaspillage se déplace chez les acheteurs","Limiter l'achat aux seuls produits non périssables"],"correct":"C","explanation":"Le passage indique : « Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. » Cela justifie la réponse : Éviter de déplacer le gaspillage vers les foyers."},{"number":21,"points":21,"passage":"Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. Les gardes ont observé des traces profondes dans certains passages très fréquentés. Ils préfèrent fermer quelques secteurs pendant une courte période plutôt que réparer plus tard un sentier fortement dégradé. Les promeneurs sont invités à suivre ces indications même lorsque la pluie a cessé et que la surface commence à sembler sèche.","question":"Quel motif explique les fermetures ?","options":["Protéger les sols affaiblis par les pluies récentes","Faciliter le passage des véhicules d'entretien","Éviter les rencontres entre groupes de promeneurs","Préparer la réfection de tous les chemins stabilisés"],"correct":"A","explanation":"Le passage indique : « Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. » Cela justifie la réponse : La fragilité temporaire du sol."},{"number":22,"points":21,"passage":"Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. Les associations du quartier proposent des points de repos temporaires et une information sur les lieux frais déjà accessibles. Le service des espaces verts a présenté le rythme probable de croissance des plantations. La mairie souhaite éviter une promesse de confort immédiat que les arbres ne peuvent pas tenir.","question":"Pourquoi ajouter d'autres équipements ?","options":["Protéger les plantations pendant les premiers travaux","Limiter l'accès à la place avant la fin du chantier","Répondre aux besoins de fraîcheur avant que les arbres grandissent","Conserver la place libre pour de futures plantations"],"correct":"C","explanation":"Le passage indique : « Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. » Cela justifie la réponse : Répondre aux besoins avant la croissance des arbres."},{"number":23,"points":21,"passage":"Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. Le personnel observe les retours de plateaux et demande aux enfants ce qui leur permet de se servir plus justement. Certains avaient l'habitude de prendre une grosse portion par crainte de manquer ensuite. Les équipes expliquent donc clairement que le complément reste possible.","question":"Quelle organisation est adoptée ?","options":["Distribuer une grande portion identique à chaque élève","Retirer le droit de se resservir pendant le repas","Servir moins d'abord, tout en permettant un complément","Réserver les portions supplémentaires au personnel"],"correct":"C","explanation":"Le passage indique : « Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. » Cela justifie la réponse : Adapter le premier service avec possibilité de complément."},{"number":24,"points":21,"passage":"Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. Les fiches précisent le lieu, la durée et les conditions de chaque sortie. Une journée sans poisson peut s'expliquer de plusieurs façons, qui seront discutées avec les spécialistes. Le groupe souhaite construire une série cohérente plutôt qu'une collection de belles photographies de captures.","question":"Pourquoi noter les sorties sans prise ?","options":["Pour calculer les prises seulement les jours fructueux","Pour comparer les durées de sortie de chaque bénévole","Pour inclure aussi les sorties sans résultat positif","Pour éviter de préciser les conditions de pêche"],"correct":"C","explanation":"Le passage indique : « Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. » Cela justifie la réponse : Pour éviter un relevé limité aux résultats positifs."},{"number":25,"points":21,"passage":"Une zone commerciale promet des bâtiments moins énergivores. Une enquête relève toutefois l'allongement des trajets automobiles provoqué par son implantation éloignée. Les économies du bâtiment ne suffisent pas à décrire l'effet global du projet. Les responsables du projet reconnaissent l'intérêt des bâtiments performants, mais demandent une comparaison avec d'autres emplacements possibles. Les distances et les moyens de transport disponibles seront intégrés au dossier. Ils souhaitent éviter qu'un progrès mesuré dans les murs masque une dépense supplémentaire provoquée ailleurs.","question":"Quel biais dans l'évaluation du projet est mis en évidence ?","options":["Mesurer les économies des bâtiments sans distinguer les usages des nouveaux commerces","Laisser hors du bilan les trajets supplémentaires dus au choix du site","Comparer les distances parcourues sans mesurer la consommation des bâtiments","Évaluer les trajets des salariés sans tenir compte de ceux des clients"],"correct":"B","explanation":"Les économies d'énergie du bâtiment ne mesurent pas l'effet des déplacements automobiles provoqués par l'éloignement. Le biais tient à ce qui est exclu du bilan."},{"number":26,"points":21,"passage":"Un agriculteur réserve une bande fleurie près de ses cultures. Elle occupe de la place, mais attire des insectes utiles. Il observe les résultats sur plusieurs saisons plutôt que promettre un bénéfice immédiat chaque année. Il a réservé un secteur témoin pour mieux comparer les évolutions avec les autres parcelles. Les variétés de fleurs ont été choisies selon leur calendrier et les conditions du sol. Certaines poussent moins bien la première année.","question":"Quelle démarche permettrait de juger le choix de l'agriculteur ?","options":["Comparer les résultats à un témoin en tenant compte de plusieurs saisons","Comparer les rendements d'une année avec ceux d'autres espèces cultivées","Suivre la diversité d'insectes avant de vérifier la réponse des parcelles","Mesurer surtout l'étendue des bandes fleuries pendant la première saison"],"correct":"A","explanation":"La bande fleurie peut aider la culture, mais l'agriculteur attend plusieurs saisons et conserve un témoin avant de juger l'effet."},{"number":27,"points":21,"passage":"Une bibliothèque d'objets prête des outils rarement utilisés. Son bilan inclut désormais leur entretien : un objet partagé longtemps peut être utile, mais un matériel rapidement cassé ne remplace pas durablement plusieurs achats. Les bénévoles contrôlent désormais les pièces sensibles et expliquent les gestes qui prolongent la durée d'utilisation. Ils enregistrent aussi les réparations pour savoir quels modèles résistent à des prêts fréquents.","question":"Quelle donnée rendrait le bilan de la bibliothèque d'objets plus pertinent ?","options":["La fréquence des emprunts indépendamment des opérations d'entretien","Le nombre de prêts qui auraient pu être remplacés par un achat neuf","Le budget consacré aux réparations au cours de la première année","La longévité réelle des objets au regard des entretiens nécessaires"],"correct":"D","explanation":"Un objet partagé n'évite durablement des achats que s'il reste utilisable assez longtemps. Le bilan comprend donc l'entretien et les défaillances."},{"number":28,"points":21,"passage":"Un collectif installe un récupérateur d'eau pour le jardin partagé. Les réserves sont affectées en priorité aux jeunes plantations pendant les restrictions. La collecte ne signifie pas que l'eau devient illimitée. Les jardiniers suivront les volumes recueillis et les besoins de chaque secteur. Une pluie importante peut remplir le réservoir, mais une période longue sans précipitations le vide rapidement. Le collectif a choisi de prévoir ces variations dans ses règles.","question":"Quelle logique explique la répartition de l'eau récupérée ?","options":["Réserver un volume stable à chaque parcelle puis ajuster les usages","Définir l'accès à l'eau selon la contribution de chaque jardinier","Distribuer les réserves en fonction des pluies précédemment reçues","Moduler l'arrosage selon les besoins urgents et les quantités disponibles"],"correct":"D","explanation":"En période de restrictions, les réserves sont dirigées vers les jeunes plantations prioritaires, plutôt que réparties de façon uniforme."},{"number":29,"points":21,"passage":"Une association propose une promenade nocturne pour observer les chauves-souris. Les participants éteignent les lampes orientées vers les refuges. Mieux voir n'autorise pas à perturber ce qu'ils viennent découvrir. Le guide présentera quelques repères sonores avant de commencer, puis choisira des points d'arrêt suffisamment éloignés des refuges. Les visiteurs pourront poser leurs questions après chaque observation pour limiter les mouvements.","question":"À quelle limite l'organisation de la visite accepte-t-elle de se soumettre ?","options":["Adapter les points d'arrêt pour rapprocher le public des refuges visibles","Limiter la qualité de l'observation si elle menace la tranquillité des animaux","Réduire le temps consacré aux explications pour observer davantage de déplacements","Maintenir les observations dans les secteurs où les chauves-souris se regroupent"],"correct":"B","explanation":"Les observations ne doivent pas perturber les chauves-souris. Le groupe reste à distance et évite d'éclairer les refuges même si cela limite la visibilité."},{"number":30,"points":26,"passage":"Le recyclage est souvent présenté comme la dernière étape évidente d'un produit. Pourtant, certains mélanges de matières sont difficiles à séparer. Un designer travaille donc sur la conception initiale : réduire cette difficulté avant la vente peut rendre le traitement final plus efficace. Des matériaux faciles à identifier et des assemblages démontables peuvent simplifier le travail des centres de traitement. Le projet associe donc les fabricants aux personnes chargées de récupérer et de séparer les produits en fin d'usage.","question":"Pourquoi le designer associe-t-il les fabricants aux spécialistes du traitement ?","options":["Pour ajuster après la vente les consignes aux matières déjà assemblées","Pour mettre les performances des machines de tri au centre du choix initial","Pour négocier les filières de reprise indépendamment de la composition des produits","Pour tenir compte dès la fabrication des obstacles rencontrés au démontage"],"correct":"D","explanation":"D. Les contraintes observées au traitement final orientent les choix de matériaux et d'assemblage dès la conception."},{"number":31,"points":26,"passage":"Une entreprise remplace ses emballages par une version plus légère. Elle doit vérifier que les produits restent protégés. Si davantage d'articles arrivent cassés, les économies d'emballage peuvent être dépassées par le coût matériel des remplacements. L'équipe réalisera des essais de transport avant de généraliser le changement. Elle regardera les emballages économisés et les articles remplacés, afin de comparer les effets sur tout le parcours plutôt que sur un seul indicateur.","question":"Quel résultat pourrait remettre en question l'intérêt du nouvel emballage ?","options":["Des dommages supplémentaires dont les remplacements annulent la matière épargnée","Des frais d'essais plus élevés que ceux engagés avant la modification","Une hausse du prix de livraison compensée par le moindre poids transporté","Une baisse de quantité de carton sans amélioration de l'image de l'entreprise"],"correct":"A","explanation":"Si un emballage plus léger laisse casser davantage de produits, les remplacements peuvent dépasser la matière économisée. Il faut comparer les effets ensemble."},{"number":32,"points":26,"passage":"Les arbres d'une avenue ont été choisis pour leur résistance à la chaleur. Un spécialiste demande aussi de varier les espèces. Une plantation homogène peut être vulnérable à une maladie qui touche précisément l'espèce retenue, même si chaque arbre supporte bien le climat. La ville choisira plusieurs variétés adaptées à ses contraintes et suivra leur état au fil des saisons. Le spécialiste veut éviter de remplacer une fragilité climatique par une autre dépendance, cette fois liée à une espèce dominante.","question":"Pourquoi la résistance à la chaleur ne suffit-elle pas à guider la plantation ?","options":["Une espèce résistante peut manquer d'adaptation aux sols de certaines rues","Une diversité de hauteurs peut compromettre l'entretien des plantations","Une plantation uniforme reste exposée à un risque sanitaire commun","Une maladie touchant une variété peut accélérer la croissance des autres"],"correct":"C","explanation":"La résistance climatique d'une seule espèce ne protège pas l'ensemble d'une maladie qui lui serait spécifique. Diversifier les variétés réduit ce risque commun."},{"number":33,"points":26,"passage":"Une campagne demande aux ménages de réduire leurs déchets. Elle obtient davantage de résultats lorsqu'elle s'accompagne de solutions pratiques : réparateurs accessibles, commerces acceptant les contenants et collecte adaptée. L'information seule laisse parfois les personnes convaincues sans possibilité d'agir facilement. Ils veulent rendre les options possibles et compréhensibles, au lieu de demander aux habitants une pratique que leur environnement quotidien ne leur permet pas facilement d'adopter.","question":"Quelle condition est jugée nécessaire pour traduire l'information en changement ?","options":["Une campagne convaincante dont les objectifs restent difficiles à quantifier","Une information diffusée sans adaptation aux habitudes locales de tri","Un dispositif associant la sensibilisation à une incitation financière","Des solutions de proximité qui rendent les comportements annoncés réalisables"],"correct":"D","explanation":"L'information n'entraîne un changement de pratiques que si les ménages disposent réellement de réparateurs, de contenants acceptés et d'une collecte adaptée."},{"number":34,"points":26,"passage":"Un chantier réemploie des portes récupérées. Certaines nécessitent plus de travail qu'un produit neuf. L'intérêt du réemploi ne se mesure donc pas seulement à la rapidité de pose : il dépend aussi des matériaux évités, des compétences mobilisées et de la durée de vie obtenue. Ils souhaitent comprendre quels objets sont réellement remis en service et dans quelles conditions, plutôt que compter tous les éléments récupérés comme des économies déjà assurées.","question":"Quel type de raisonnement les responsables du chantier cherchent-ils à éviter ?","options":["Déduire la qualité des éléments récupérés de leur rapidité d'installation","Choisir les portes réemployées avant d'examiner les contraintes techniques","Évaluer le réemploi sans intégrer le coût du travail de remise en état","Compter la récupération comme une économie avant de vérifier le réemploi"],"correct":"D","explanation":"Une porte simplement récupérée n'est pas forcément remise en service. Le bénéfice du réemploi dépend aussi du travail nécessaire et de la durée de vie."},{"number":35,"points":26,"passage":"Une réserve naturelle augmente sa surface protégée. Cependant, une route coupe la liaison entre deux secteurs. Pour certains animaux, la continuité des habitats compte autant que leur superficie. Ajouter des hectares séparés peut donc améliorer un indicateur sans résoudre la principale difficulté écologique. Leur travail porte ainsi sur l'organisation de l'espace, car certains besoins ne peuvent pas être satisfaits par une simple augmentation des surfaces figurant sur la carte.","question":"Pourquoi l'augmentation de la surface protégée reste-t-elle insuffisante ?","options":["La surface supplémentaire peut être protégée sans disposer d'un suivi écologique","L'ajout de terrain ne rétablit pas les liens physiques coupés entre habitats","Le nombre d'hectares peut augmenter alors que les espèces deviennent plus rares","Une zone plus vaste exige des moyens de surveillance plus importants"],"correct":"B","explanation":"La route rompt les continuités entre deux secteurs protégés. La superficie supplémentaire ne permet pas à elle seule aux animaux de circuler entre ces habitats."},{"number":36,"points":33,"passage":"Une municipalité propose des sacs recyclables pour ses événements. Une équipe constate que beaucoup sont jetés avec des restes alimentaires, rendant leur traitement difficile. Le choix du matériau n'était qu'une partie du problème. Sans organisation de la collecte et consignes compréhensibles, une possibilité technique de recyclage ne devient pas nécessairement un recyclage effectif. Le service d'entretien doit savoir où déposer les sacs et comment distinguer les déchets acceptés. Les participants reçoivent aussi des consignes au moment où ils utilisent le matériel, plutôt qu'une longue notice uniquement visible avant l'événement. Les organisateurs mesureront donc les quantités effectivement orientées vers le bon traitement. Ils souhaitent comparer plusieurs options, y compris la réduction du nombre de sacs distribués. Le choix d'un matériau reste important, mais le bilan doit tenir compte des gestes et des équipements qui rendent sa récupération possible dans les conditions réelles du festival.","question":"Quel indicateur serait le plus fidèle à l'objectif de la municipalité ?","options":["La proportion de sacs achetés avec une indication de recyclabilité","La quantité de sacs parvenant réellement au traitement approprié","La proportion de personnes ayant reçu les consignes de tri","La réduction du nombre de sacs nécessaires au déroulement du festival"],"correct":"B","explanation":"Des sacs techniquement recyclables peuvent être jetés avec des restes et mal traités. Le résultat pertinent est leur orientation effective vers une filière appropriée."},{"number":37,"points":33,"passage":"Pour améliorer un cours d'eau, une association supprime certains obstacles et restaure des berges. Les résultats évoluent lentement et varient selon les saisons. Des financeurs souhaiteraient un chiffre simple chaque mois. L'équipe défend un suivi de plusieurs indicateurs sur plusieurs années. L'absence d'une hausse immédiate et régulière ne suffit pas à conclure à l'échec d'une restauration écologique. Certains effets se manifestent par le retour progressif d'espèces, d'autres par une meilleure circulation de l'eau ou par l'évolution de la végétation. Une crue peut modifier temporairement un relevé sans annuler les progrès réalisés. L'association souhaite expliquer ces variations aux habitants et aux partenaires financiers. Elle ne demande pas d'échapper à toute évaluation : elle veut un suivi capable de distinguer une difficulté durable d'une fluctuation normale.","question":"Pourquoi un seul chiffre mensuel risque-t-il de déformer le jugement ?","options":["Un relevé influencé par une crue devrait être retiré du suivi plutôt qu'expliqué","Un relevé peut être dominé par un épisode ponctuel sans indiquer les évolutions durables","Les effets sur les espèces devraient être relevés uniquement à la fin du programme","La circulation de l'eau devrait devenir le seul indicateur transmis aux financeurs"],"correct":"B","explanation":"B. Les effets écologiques se manifestent sur des périodes différentes et varient selon les saisons; l'équipe demande donc plusieurs indicateurs suivis dans la durée. A propose de retirer les relevés atypiques alors que le passage demande de les interpréter, et C/D réduisent la variété des mesures."},{"number":38,"points":33,"passage":"Une marque met en avant une forte baisse de consommation pour chaque appareil vendu. Dans le même temps, elle encourage les clients à multiplier les équipements connectés dans leur logement. Le bilan individuel s'améliore, mais le nombre d'appareils augmente. Une meilleure efficacité par unité ne garantit pas une réduction de la consommation totale. Les équipes commerciales mettent surtout en avant la performance du dernier modèle, sans toujours évoquer les achats supplémentaires qu'elles encouragent. Une association de consommateurs propose de présenter des exemples d'équipement complet d'un logement. Les ménages pourraient alors comparer plusieurs choix à usage semblable. La marque reconnaît qu'une amélioration technique peut être réelle tout en donnant un résultat différent à l'échelle de l'ensemble des ventes. Le débat porte donc à la fois sur les caractéristiques des appareils et sur les pratiques de renouvellement qu'un modèle commercial cherche à installer.","question":"Quelle limite du discours commercial le texte invite-t-il à examiner ?","options":["Les ventes supplémentaires sont nécessaires pour financer l'efficacité des appareils","La performance technique affichée dépend des conditions d'installation de chaque modèle","Les gains sont calculés sur un équipement alors que les usages se multiplient","Les comparaisons entre appareils masquent les dépenses liées à leur fabrication"],"correct":"C","explanation":"Une baisse de consommation pour chaque appareil ne garantit pas une baisse totale lorsque la marque encourage à multiplier les équipements."},{"number":39,"points":33,"passage":"La plantation d'arbres est parfois proposée comme compensation immédiate d'émissions présentes. Les arbres peuvent contribuer au stockage du carbone, mais leur croissance prend du temps et leur survie dépend des conditions locales. Annoncer une équivalence instantanée efface ces incertitudes et risque de faire passer une promesse future pour un résultat déjà acquis. Une sécheresse, une maladie ou un changement d'usage du terrain peut réduire le stockage attendu. Les responsables d'un programme sérieux doivent donc préciser le suivi, la durée et les hypothèses sur lesquelles reposent leurs estimations. Des plantations peuvent apporter d'autres bénéfices utiles, notamment pour le paysage et la biodiversité. Ces intérêts ne doivent toutefois pas servir à faire disparaître les différences entre une réduction déjà obtenue et un engagement à long terme. Les citoyens ont besoin de ces informations pour comprendre la portée réelle des annonces et comparer des actions différentes.","question":"Quel glissement est particulièrement visé par l'annonce d'une « compensation immédiate » ?","options":["Traiter un stockage futur envisagé comme une réduction déjà obtenue","Assimiler une croissance attendue à une garantie de survie des plantations","Prendre les bénéfices paysagers pour la preuve d'un suivi rigoureux","Présenter une première estimation de stockage comme une mesure définitive"],"correct":"A","explanation":"L'annonce assimile une absorption future, dépendante du temps et de la survie des arbres, à une réduction déjà réalisée : A. B et D évoquent des incertitudes réelles mais pas l'équivalence temporelle qui fonde l'annonce de compensation immédiate; C confond un avantage annexe et la qualité du suivi."}]}$paper$::jsonb),
('tcf-reading-06','tcf-reading-2026-11-advanced-v5',$paper${"id":"tcf-reading-06","version":"tcf-reading-2026-11-advanced-v5","title":"TCF Reading · Test 06","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre.\n\nLes spectateurs sont invités à venir assez tôt pour s'installer. Le personnel indiquera les accès sans réserver de fauteuil particulier.","question":"À partir de quand peut-on entrer ?","options":["Vingt heures","Dix-neuf heures trente","Dix-huit heures précises","Dix-huit heures trente"],"correct":"D","explanation":"Le passage indique : « Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre. » Cela justifie la réponse : Dix-huit heures trente."},{"number":2,"points":3,"passage":"La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires.\n\nLes œuvres fragiles seront déplacées par l'équipe technique. Aucun accueil de groupe ne sera assuré pendant cette installation.","question":"Pourquoi la galerie ferme-t-elle ?","options":["Pour réduire ses horaires","Pour installer une exposition","Pour organiser un concert","Pour vendre le bâtiment"],"correct":"B","explanation":"Le passage indique : « La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires. » Cela justifie la réponse : Pour installer une exposition."},{"number":3,"points":3,"passage":"Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu.\n\nUne fiche permettra de signaler une déchirure ou une pièce perdue.","question":"Que faut-il éviter ?","options":["Laver soi-même les costumes","Les rapporter vendredi matin","Les rendre avant midi","Utiliser la réception"],"correct":"A","explanation":"Le passage indique : « Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu. » Cela justifie la réponse : Laver soi-même les costumes."},{"number":4,"points":3,"passage":"La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte.\n\nLes partitions et le matériel seront transportés par les bénévoles. Les chanteurs sont invités à consulter le panneau à l'entrée avant de s'installer.","question":"Qu'est-ce qui change ?","options":["Le jour de la répétition","Le groupe de chanteurs","La salle de répétition","La porte d'entrée"],"correct":"C","explanation":"Le passage indique : « La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte. » Cela justifie la réponse : La salle de répétition."},{"number":5,"points":9,"passage":"Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage.\n\nElle souhaite surtout revoir les transitions et l'ordre des entrées. Je lui transmettrai aussi mes annotations pour éviter de lui laisser des détails à découvrir au dernier moment.","question":"Pourquoi une répétition supplémentaire est-elle prévue ?","options":["Préparer un remplacement","Vendre les instruments","Choisir la date du concert","Composer une nouvelle œuvre"],"correct":"A","explanation":"Le passage indique : « Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage. » Cela justifie la réponse : Préparer un remplacement."},{"number":6,"points":9,"passage":"L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever.\n\nLes manches longues sont recommandées pour protéger les vêtements. L'animateur montrera les gestes à réaliser avant de commencer le premier tirage.","question":"Quel objet doit apporter le participant ?","options":["Du papier","De l'encre","Une blouse","Une presse"],"correct":"C","explanation":"Le passage indique : « L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever. » Cela justifie la réponse : Une blouse."},{"number":7,"points":9,"passage":"Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne.\n\nVous pouvez confirmer en ligne ou par téléphone. Cette règle permet à la billetterie de proposer les places non utilisées sans retarder le début de la représentation.","question":"Quel risque existe sans confirmation ?","options":["Le spectacle commence plus tôt","La salle devient privée","La place peut être réattribuée","Le billet est envoyé par courrier"],"correct":"C","explanation":"Le passage indique : « Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne. » Cela justifie la réponse : La place peut être réattribuée."},{"number":8,"points":9,"passage":"Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies.\n\nLes noms seront ensuite présentés avec quelques informations sur le travail de chaque photographe.","question":"Quel est le but de ce choix ?","options":["Vendre les biographies séparément","Interdire les discussions","Cacher définitivement les artistes","Regarder d'abord les œuvres elles-mêmes"],"correct":"D","explanation":"Le passage indique : « Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies. » Cela justifie la réponse : Regarder d'abord les œuvres elles-mêmes."},{"number":9,"points":9,"passage":"Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres.\n\nL'équipe souhaite accueillir les personnes gênées par les conditions d'une séance ordinaire, sans leur demander d'expliquer publiquement leur situation.","question":"À quel besoin cette séance répond-elle ?","options":["Un film réservé aux critiques","Une projection plus rapide","Une salle entièrement obscure","Un environnement sensoriel plus souple"],"correct":"D","explanation":"Le passage indique : « Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres. » Cela justifie la réponse : Un environnement sensoriel plus souple."},{"number":10,"points":9,"passage":"Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain.\n\nRéserve assez tôt si tu veux venir un samedi, car ces soirées se remplissent souvent rapidement. Nous pourrons y aller ensemble.","question":"Que peut décider le destinataire ?","options":["L'heure d'ouverture du théâtre","Le programme de la saison","Le nom des danseurs","La représentation à laquelle assister"],"correct":"D","explanation":"Le passage indique : « Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain. » Cela justifie la réponse : La représentation à laquelle assister."},{"number":11,"points":15,"passage":"Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques.\n\nLes comédiens ont construit des éléments qui peuvent changer de fonction et tenir dans un espace réduit. Une répétition sur place permet d'adapter les entrées et les déplacements au lieu du jour. Les habitants viennent parfois installer des chaises avant le spectacle. L'équipe ne cherche pas à reproduire une grande scène partout : elle veut conserver une qualité de jeu tout en acceptant les particularités de chaque village.","question":"Qu'est-ce qui facilite ces déplacements ?","options":["Une absence de répétitions","Un décor facilement transportable","Une scène permanente dans chaque village","Un spectacle sans interprètes"],"correct":"B","explanation":"Le passage indique : « Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques. » Cela justifie la réponse : Un décor facilement transportable."},{"number":12,"points":15,"passage":"Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles.\n\nLes objets ont été réalisés à une échelle permettant de sentir les contours et les volumes. Un médiateur explique les différences avec l'œuvre exposée, afin de ne pas présenter la copie comme une expérience identique. Les visiteurs peuvent poser des questions avant de revenir regarder l'original.","question":"Quel est leur intérêt ?","options":["Authentifier les œuvres vendues","Remplacer tous les originaux","Découvrir les formes par le toucher","Supprimer les visites guidées"],"correct":"C","explanation":"Le passage indique : « Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles. » Cela justifie la réponse : Découvrir les formes par le toucher."},{"number":13,"points":15,"passage":"La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande.\n\nL'illustrateur dispose d'une table de travail accessible pendant quelques heures annoncées. Il pourra montrer un carnet ou expliquer un choix de composition, selon l'étape de son projet. La bibliothèque veut rendre le processus de création plus visible, tout en laissant à l'artiste le temps nécessaire pour chercher et recommencer. Les rencontres avec les classes seront préparées séparément. Cette organisation doit éviter que la résidence devienne une succession de commandes rapides empêchant le travail prévu sur l'album.","question":"Quelle activité n'est pas promise ?","options":["Dessiner pour chaque demande individuelle","Rencontrer des lecteurs","Créer un album","Travailler sur place"],"correct":"A","explanation":"Le passage indique : « La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande. » Cela justifie la réponse : Dessiner pour chaque demande individuelle."},{"number":14,"points":15,"passage":"Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat.\n\nLes enseignants présentent plusieurs modèles et vérifient que leur taille convient à l'élève. Les familles reçoivent des consignes d'entretien et peuvent signaler une difficulté pendant la période d'essai. À la fin du trimestre, un échange permet de décider s'il faut poursuivre ou explorer une autre possibilité. Le conservatoire souhaite éviter qu'un achat important soit réalisé avant que la personne ait découvert les exigences réelles de la pratique.","question":"Quel avantage est offert ?","options":["Tester un instrument avant de l'acheter","Éviter toute pratique personnelle","Recevoir un instrument définitivement gratuit","Choisir sans jamais essayer"],"correct":"A","explanation":"Le passage indique : « Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat. » Cela justifie la réponse : Tester un instrument avant de l'acheter."},{"number":15,"points":15,"passage":"Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement.\n\nLors des essais, certaines personnes voyaient bien les comédiens mais devaient tourner constamment la tête pour suivre le texte. La billetterie donnera désormais des informations sur ces différences de visibilité. Les clients pourront choisir selon leurs besoins et les places disponibles. Le théâtre ne présente pas tous les sièges comme équivalents pour chaque usage. Il veut limiter les déceptions qui apparaissent lorsqu'un service annoncé existe techniquement, mais reste difficile à utiliser depuis une partie de la salle.","question":"Quel critère guide cette recommandation ?","options":["Le prix du programme","La proximité du vestiaire","La lisibilité des sous-titres","L'accès aux coulisses"],"correct":"C","explanation":"Le passage indique : « Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement. » Cela justifie la réponse : La lisibilité des sous-titres."},{"number":16,"points":15,"passage":"Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale.\n\nLes visiteurs observent des phrases déplacées, des mots remplacés et parfois des pages presque entièrement abandonnées. Des notes expliquent le contexte de ces modifications. Les commissaires ont voulu rendre sensible le temps de recherche derrière un ouvrage connu. Ils ne présentent pas le brouillon comme un texte moins valable à corriger une dernière fois, mais comme une étape permettant de comprendre des décisions.","question":"Que découvrent les visiteurs ?","options":["Le travail progressif de l'écriture","Les revenus exacts de l'auteur","Une version sans aucune modification","La disparition de tous les manuscrits"],"correct":"A","explanation":"Le passage indique : « Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale. » Cela justifie la réponse : Le travail progressif de l'écriture."},{"number":17,"points":15,"passage":"Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association.\n\nLes bénéficiaires pourront présenter une facture ou un document courant, sans remplir un dossier compliqué. L'association de quartier aidera les personnes qui rencontrent une difficulté lors de la réservation. Le festival souhaite retrouver un public qui vit près des salles mais ne les fréquente pas toujours. Les organisateurs vérifieront si les billets sont réellement utilisés, car une réduction annoncée ne suffit pas à créer une habitude de sortie ou à faire connaître le programme aux habitants.","question":"Quelle pièce est demandée ?","options":["Une adhésion associative","Un justificatif de domicile","Une attestation de voyage","Une carte professionnelle"],"correct":"B","explanation":"Le passage indique : « Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association. » Cela justifie la réponse : Un justificatif de domicile."},{"number":18,"points":15,"passage":"Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final.\n\nLes échanges portent notamment sur les noms, les dates et les faits précis mentionnés à l'oral. Le réalisateur peut expliquer pourquoi certains passages sont raccourcis pour être compris par le public. Il souhaite construire une relation claire avec les témoins sans leur attribuer la responsabilité de tout le film. L'accord sur une citation ne signifie donc pas que chacun approuve l'ensemble du récit.","question":"Quel contrôle leur est accordé ?","options":["Décider de toutes les images","Choisir tous les autres témoins","Remplacer le réalisateur","Vérifier l'exactitude de leurs propos"],"correct":"D","explanation":"Le passage indique : « Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final. » Cela justifie la réponse : Vérifier l'exactitude de leurs propos."},{"number":19,"points":15,"passage":"Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation.\n\nLes animateurs proposent d'abord de petites consignes puis laissent un temps d'écriture silencieuse. Les textes ne sont pas classés du meilleur au moins réussi. Les échanges portent sur ce que l'on comprend, sur les effets recherchés et sur les possibilités de reprise. Le groupe veut favoriser des essais sans transformer chaque séance en évaluation publique.","question":"Quelle règle favorise l'accueil ?","options":["Seuls les auteurs expérimentés peuvent écouter","Les débutants doivent se taire","Tous doivent publier un livre","La lecture de son texte reste facultative"],"correct":"D","explanation":"Le passage indique : « Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation. » Cela justifie la réponse : La lecture de son texte reste facultative."},{"number":20,"points":21,"passage":"Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués. Les captations sont proposées sur une période limitée après les représentations. L'équipe améliore le son et les sous-titres, sans prétendre que l'écran remplace exactement la salle. Elle souhaite toucher les personnes empêchées de se déplacer, tout en maintenant des occasions de discussion pour celles qui peuvent venir. Le bilan distinguera ces usages plutôt que les opposer comme deux publics nécessairement concurrents.","question":"Que veut-elle préserver ?","options":["L'absence de contact avec le public","Une dimension sociale de la sortie","La suppression des échanges spontanés","Une exclusivité complète sur place"],"correct":"B","explanation":"Le passage indique : « Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués. » Cela justifie la réponse : Une dimension sociale de la sortie."},{"number":21,"points":21,"passage":"Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique. Les réunions commencent par une présentation du travail de l'artiste et des contraintes techniques. Les participants peuvent expliquer comment ils traversent la place et où ils aiment s'arrêter. Le comité veut ainsi éviter qu'une œuvre soit installée sans rapport avec la vie du lieu. L'auteur conserve toutefois la responsabilité de ses choix formels, dans le cadre de la commande discutée.","question":"Quelle est la portée de la consultation ?","options":["Elle supprime le travail de l'artiste","Elle concerne l'insertion de l'œuvre dans l'espace public","Elle fixe tous les gestes du sculpteur","Elle décide du prix des billets"],"correct":"B","explanation":"Le passage indique : « Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique. » Cela justifie la réponse : Elle concerne l'insertion de l'œuvre dans l'espace public."},{"number":22,"points":21,"passage":"Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir. Une enquête est proposée aux familles et aux adultes inscrits, avec une version accessible par téléphone. Le conservatoire étudie aussi des séances ponctuelles le week-end. Il ne veut pas considérer les absences comme la preuve que les personnes ne s'intéressent pas à la musique. Le bilan portera sur les conditions qui permettent effectivement de venir, pas uniquement sur l'absence d'examen annoncée dans la brochure.","question":"Quelle limite subsiste ?","options":["Un examen est obligatoire partout","Les ateliers ne disposent d'aucun enseignant","Les horaires peuvent encore exclure des participants","Aucun adulte ne souhaite apprendre"],"correct":"C","explanation":"Le passage indique : « Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir. » Cela justifie la réponse : Les horaires peuvent encore exclure des participants."},{"number":23,"points":21,"passage":"Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle. Les lecteurs rencontrent les écrivains plusieurs fois, suivent la préparation d'un livre et recommandent ensuite certains titres à leurs proches. La librairie réserve une petite table à ces découvertes pour qu'elles ne disparaissent pas immédiatement des rayons. Elle sait que les recettes doivent rester suffisantes pour faire vivre le lieu.","question":"Quel effet est décrit ?","options":["Un succès immédiat garanti","Un abandon de tous les petits éditeurs","La disparition des rencontres","La construction lente d'un lectorat"],"correct":"D","explanation":"Le passage indique : « Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle. » Cela justifie la réponse : La construction lente d'un lectorat."},{"number":24,"points":21,"passage":"Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes. Les personnes rencontrées sont informées de cette transformation et peuvent assister à une répétition. Certaines reconnaissent un détail, d'autres découvrent une scène qui rassemble plusieurs expériences. Le spectacle sera accompagné d'une discussion sur cette différence, afin que le public puisse apprécier le travail de création et comprendre la manière dont les témoignages l'ont nourri.","question":"Pourquoi cette précision importe-t-elle ?","options":["Distinguer création artistique et fidélité documentaire","Remplacer tous les témoignages","Interdire toute interprétation","Garantir l'exactitude de chaque dialogue"],"correct":"A","explanation":"Le passage indique : « Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes. » Cela justifie la réponse : Distinguer création artistique et fidélité documentaire."},{"number":25,"points":21,"passage":"Un théâtre réduit son décor pour diminuer les transports. La mise en scène utilise davantage la lumière et les mouvements. La sobriété matérielle devient un choix artistique autant qu'une contrainte logistique. Les artistes ont d'abord testé les possibilités dans une petite salle, avec quelques éléments transformables. Certaines contraintes ont fait apparaître des solutions auxquelles ils n'avaient pas pensé auparavant. Le metteur en scène souhaite conserver cette recherche dans la version finale.","question":"Quelle transformation artistique découle de la contrainte matérielle ?","options":["L'allégement des décors change essentiellement les déplacements de matériel","La contrainte de sobriété conduit à repenser aussi les formes scéniques","La petite salle permet des essais sans rapport avec la mise en scène finale","Le nombre de décors demeure stable grâce aux éléments transformables"],"correct":"B","explanation":"Le décor réduit les transports, mais fait aussi évoluer la mise en scène vers la lumière et le mouvement. La contrainte devient une ressource esthétique."},{"number":26,"points":21,"passage":"Une médiatrice recueille les impressions avant d'expliquer un tableau. Elle veut que les visiteurs osent regarder sans chercher immédiatement une interprétation autorisée. Les premières remarques sont accueillies sans chercher immédiatement à les corriger. Les explications viennent ensuite apporter des repères historiques ou techniques. Les visiteurs peuvent comparer ce qu'ils avaient ressenti et ce qu'ils comprennent après l'échange. Le musée souhaite ainsi éviter que la peur de se tromper empêche de regarder.","question":"Quelle démarche organise la découverte du tableau ?","options":["Les repères historiques sont apportés pour confirmer les premières impressions","Le regard personnel est recueilli avant les informations techniques ou historiques","Les participants confrontent leurs réactions une fois la bonne lecture établie","La médiatrice corrige progressivement les hypothèses pendant l'observation initiale"],"correct":"B","explanation":"La médiatrice accueille d'abord les impressions des visiteurs, puis propose des repères qui permettent de revisiter ces premières perceptions."},{"number":27,"points":21,"passage":"Une collection privée est accessible sur rendez-vous. Son propriétaire publie des images en ligne, mais certaines fragilités matérielles justifient de limiter les visites physiques. Le nombre de visiteurs est adapté aux pièces et à leur capacité d'accueil. Certains documents restent accessibles uniquement sous forme de reproduction pour éviter des manipulations répétées. Les chercheurs peuvent contacter le responsable pour préciser leur demande.","question":"Quel motif justifie la restriction des visites sur place ?","options":["Le rendez-vous sert d'abord à sélectionner les demandes selon leur intérêt","Les images publiées remplacent désormais l'accès aux documents originaux","La fréquence des visites est adaptée pour éviter d'endommager les pièces","Les chercheurs doivent justifier l'utilisation des reproductions numériques"],"correct":"C","explanation":"La fragilité de certaines pièces rend nécessaires des limites de visites et de manipulation. Les reproductions maintiennent un accès à l'information."},{"number":28,"points":21,"passage":"Une maison d'édition publie simultanément un livre papier et une version audio. Les deux formats répondent à différents usages ; les éditeurs ne présentent pas l'un comme la disparition de l'autre. Les personnes qui écoutent pendant un trajet ne rencontrent pas les mêmes contraintes que celles qui consultent un passage à une table. Les équipes travaillent donc les deux versions avec des exigences propres, notamment pour la navigation et la qualité de la lecture.","question":"Quelle relation entre les éditions guide la politique de publication ?","options":["L'audio offre une solution provisoire aux lecteurs qui ne trouvent pas le papier","L'éditeur traite l'audio comme une version secondaire du texte imprimé","Les deux supports visent les mêmes usages mais à des heures différentes","Les formats répondent à des besoins distincts sans se remplacer mutuellement"],"correct":"D","explanation":"Les deux supports répondent à des situations différentes ; leur conception requiert des qualités propres, sans que l'un soit destiné à remplacer l'autre."},{"number":29,"points":21,"passage":"Un festival mesure aussi la satisfaction des bénévoles. Une organisation épuisante pourrait compromettre les éditions suivantes, même si le public actuel est nombreux. Le questionnaire porte sur la répartition des tâches, les pauses et la clarté des consignes. Les responsables veulent savoir si les nouveaux volontaires ont pu trouver leur place sans dépendre constamment des organisateurs habituels. Les réponses serviront à préparer l'année suivante.","question":"Pourquoi la satisfaction des bénévoles est-elle prise en compte dans le bilan ?","options":["Identifier les bénévoles les plus disponibles pour les tâches des années suivantes","Répartir les pauses pour améliorer immédiatement le nombre de visiteurs","Vérifier si des consignes détaillées dispensent de recruter de nouveaux volontaires","Tenir compte des conditions vécues par les bénévoles pour pérenniser le festival"],"correct":"D","explanation":"La fatigue et la qualité de l'accueil des bénévoles affectent la possibilité d'organiser les prochaines éditions malgré l'affluence actuelle."},{"number":30,"points":26,"passage":"Un abonnement culturel donne accès à de nombreux lieux. Pourtant, les personnes qui ne connaissent pas les programmes l'utilisent peu. Un accompagnement à la découverte est ajouté : disposer d'un droit d'entrée ne suffit pas toujours à se sentir invité. Des présentations courtes et des échanges avec des lecteurs familiers sont donc proposés. La bibliothèque souhaite permettre une première visite concrète, sans supposer que tous les bénéficiaires savent déjà où aller ni comment choisir une activité.","question":"Quelle difficulté l'accompagnement ajouté cherche-t-il à résoudre ?","options":["Permettre à ceux qui disposent déjà d'un droit d'entrée de savoir comment en profiter","Rendre l'abonnement accessible en réduisant le nombre d'activités proposées","Remplacer les rencontres avec des lecteurs par une présentation préalable obligatoire","Orienter les personnes en fonction des seuls lieux déjà présents dans l'abonnement"],"correct":"A","explanation":"Un droit d'entrée inutilisé faute de repères ne donne pas pleinement accès à la culture. Présentations et échanges facilitent la première visite."},{"number":31,"points":26,"passage":"Les restaurateurs d'une fresque conservent des traces de transformations anciennes. Leur objectif n'est pas de fabriquer une surface paraissant neuve, mais de rendre l'œuvre lisible en respectant son histoire. La restauration suppose donc des choix, pas un simple effacement du temps. Les notices expliquent les interventions anciennes et celles réalisées aujourd'hui. Les visiteurs pourront distinguer une réparation indispensable d'un choix de présentation.","question":"Quel principe guide le traitement des marques laissées sur la fresque ?","options":["Préserver la lisibilité de l'œuvre sans effacer les marques de son histoire","Rendre apparentes les restaurations récentes plutôt que les traces anciennes","Reconstituer l'apparence initiale en distinguant les ajouts postérieurs","Conserver les transformations même lorsqu'elles empêchent de lire la fresque"],"correct":"A","explanation":"A. Le traitement doit ménager lisibilité et histoire matérielle; les interventions anciennes ne sont pas à effacer."},{"number":32,"points":26,"passage":"Un succès en ligne conduit un groupe à jouer dans une grande salle. Les musiciens découvrent que l'attention d'un public assis diffère des réactions fragmentées sur une plateforme. La notoriété numérique facilite la rencontre, mais ne dispense pas d'adapter le spectacle. Le groupe essaie plusieurs formats et observe comment les morceaux changent dans l'espace de la salle. Les retours du public aideront à préparer les prochains concerts, sans transformer chaque réaction immédiate en verdict définitif sur leur musique.","question":"Quelle limite du succès numérique apparaît lors du passage sur scène ?","options":["La réaction en salle permet de mesurer plus précisément la popularité en ligne","La notoriété acquise dispense de préparer le concert mais pas son acoustique","Le public réuni impose d'adapter une réussite initialement obtenue en ligne","Les retours recueillis après les concerts déterminent seuls la valeur des morceaux"],"correct":"C","explanation":"La popularité numérique attire un public, mais la situation d'un concert exige des choix scéniques que les réactions sur plateforme ne déterminent pas."},{"number":33,"points":26,"passage":"Une exposition multiplie les écrans pour attirer les jeunes. Certains visiteurs apprécient l'interactivité ; d'autres regrettent de moins voir les objets. L'équipe réaménage des zones plus calmes. Elle ne renonce pas aux outils, mais cherche un équilibre entre médiation et présence des œuvres. Le parcours laisse cependant des moments où l'on peut simplement regarder une œuvre, sans devoir accomplir une action ou lire une nouvelle consigne.","question":"Quelle orientation caractérise la nouvelle organisation de l'exposition ?","options":["Les écrans sont déplacés dans des salles séparées afin de rendre les œuvres plus visibles","La visite conserve les dispositifs mais ménage davantage d'observation directe","La médiation interactive est réservée aux visiteurs qui connaissent les collections","L'équipe limite les contenus disponibles pour éviter de ralentir le parcours"],"correct":"B","explanation":"L'équipe ne supprime ni écrans ni informations : elle réintroduit des espaces où l'on peut regarder les œuvres directement."},{"number":34,"points":26,"passage":"Une œuvre participative invite chacun à ajouter un fragment. L'artiste fixe cependant une règle commune afin que les contributions puissent dialoguer. Participer n'équivaut donc pas à agir sans cadre. La liberté s'exerce dans une structure qui rend la création collective possible. La règle n'efface donc pas les différences individuelles : elle leur donne un espace où elles peuvent être perçues ensemble, plutôt que se masquer mutuellement.","question":"Quelle fonction commune la règle donne-t-elle aux contributions ?","options":["Le cadre commun permet de distinguer les contributions au sein d'un ensemble cohérent","La règle sert à répartir équitablement le nombre de fragments entre participants","L'artiste utilise les mêmes motifs pour atténuer les différences entre les ajouts","Les fragments restent indépendants pour préserver la liberté individuelle"],"correct":"A","explanation":"Une règle partagée organise la rencontre de fragments différents. Elle rend les contributions lisibles ensemble sans les rendre identiques."},{"number":35,"points":26,"passage":"Les statistiques de fréquentation valorisent les grandes expositions. Un musée examine aussi les retours de petits groupes accompagnés sur plusieurs séances. Leur nombre est faible, mais leur relation aux œuvres devient plus approfondie. La quantité des entrées ne décrit pas à elle seule tous les effets culturels. Elles souhaitent mieux comprendre ce que les visiteurs découvrent et conservent de leur expérience, au-delà du simple passage devant une porte d'entrée.","question":"Quelle évolution des critères d'évaluation est proposée ?","options":["Écarter les données d'affluence pour privilégier l'expérience des petits groupes","Comparer les groupes selon le nombre d'entrées qu'ils génèrent après chaque visite","Compléter la fréquentation par l'étude de ce que les visiteurs retirent des œuvres","Mesurer la satisfaction des visiteurs pour prévoir la taille des futures expositions"],"correct":"C","explanation":"C. L'évaluation ajoute la profondeur de la relation aux œuvres à la fréquentation, sans supprimer l'indicateur quantitatif."},{"number":36,"points":33,"passage":"Une ville souhaite transformer un atelier d'artistes en attraction permanente. Les créateurs apprécient l'intérêt du public, mais craignent de devoir montrer un travail immédiatement compréhensible à toute heure. Certaines recherches exigent des essais sans résultat présentable. Rendre la création visible ne doit pas obliger à confondre le temps de recherche et celui de la représentation. Les artistes expliquent que des journées entières peuvent être nécessaires pour essayer une matière ou abandonner une piste. Une visite constante risquerait de les conduire à répéter les gestes les plus faciles à montrer, au détriment du travail qui justifie leur présence. Ils proposent des créneaux de rencontre annoncés et des moments protégés. La ville accepte d'observer cette organisation avant de fixer un calendrier permanent. L'intérêt du projet tient alors autant à la qualité des échanges possibles qu'au respect du processus que les visiteurs souhaitent découvrir.","question":"Quel risque principal accompagne l'ouverture permanente de l'atelier ?","options":["L'obligation de montrer des résultats pourrait évincer les essais encore incertains","La médiation réduirait le temps consacré aux seules commandes d'œuvres achevées","Le calendrier de visites déplacerait les recherches vers les jours de fermeture","L'accès continu pourrait limiter les collaborations avec les visiteurs intéressés"],"correct":"A","explanation":"A. La présence permanente du public favorise les gestes faciles à montrer au détriment de recherches et essais non immédiatement présentables."},{"number":37,"points":33,"passage":"Un documentaire donne la parole à des habitants longtemps absents des médias. Le réalisateur refuse pourtant de présenter ces voix comme un groupe parfaitement homogène. Les désaccords font partie de leur expérience commune. Accorder une visibilité ne consiste pas à fabriquer une parole unique qui effacerait les différences internes. Certains témoins ont des intérêts proches mais des souvenirs contradictoires d'un même événement. Le réalisateur les laisse apparaître, en donnant au spectateur les éléments nécessaires pour comprendre leurs positions. Il refuse d'effacer les nuances simplement pour obtenir un récit plus facile à résumer. Les participants sont informés du cadre et peuvent vérifier leurs propres propos avant diffusion. Cette méthode ne prétend pas supprimer tous les choix du montage, mais rend moins plausible l'idée qu'une personne pourrait parler naturellement au nom de toutes celles qui partagent son lieu de vie.","question":"Quelle simplification des témoignages le réalisateur refuse-t-il ?","options":["Attribuer les divergences à des souvenirs différents avant de les confronter","Faire apparaître les positions des habitants sans expliquer leurs désaccords","Laisser les témoins valider leurs propos avant d'en présenter plusieurs versions","Traiter la visibilité des habitants comme l'expression d'une parole commune et uniforme"],"correct":"D","explanation":"D. Le réalisateur refuse la fabrication d'une voix homogène qui effacerait les désaccords internes."},{"number":38,"points":33,"passage":"Une plateforme recommande des livres proches de ceux déjà lus. Ce service aide à choisir, mais peut réduire les découvertes inattendues. Une libraire propose à ses clients un titre éloigné de leurs habitudes, en expliquant le lien possible avec leurs intérêts. Découvrir ne suppose pas forcément l'absence de repères, mais parfois un déplacement accompagné de ces repères. Elle demande parfois au lecteur quel passage il avait préféré et ce qui l'avait surpris. À partir de ces éléments, elle propose une autre forme de récit ou une période moins familière, en laissant la possibilité de refuser. Le conseil devient une invitation argumentée, pas un classement établi une fois pour toutes. Les clients peuvent revenir expliquer ce qu'ils ont apprécié ou abandonné. Cette relation permet de varier progressivement les propositions et de comprendre qu'une lecture difficile au début peut aussi ouvrir un intérêt durable, sans que cette issue soit garantie pour chacun.","question":"Quelle manière d'élargir les choix de lecture est proposée ?","options":["Mettre les évaluations des lecteurs en commun pour établir des classements plus fiables","S'appuyer sur certains goûts du lecteur afin de l'amener vers des univers nouveaux","Choisir des œuvres très éloignées des habitudes sans évoquer les points communs","Proposer des lectures moins difficiles avant d'aborder des genres différents"],"correct":"B","explanation":"La libraire part de goûts connus pour proposer un déplacement argumenté vers des œuvres moins familières, sans forcer l'adhésion."},{"number":39,"points":33,"passage":"On associe parfois un grand nombre de visiteurs à la réussite d'un lieu culturel. Dans une petite salle, l'augmentation des entrées a réduit le temps d'échange et rendu certaines personnes moins à l'aise. L'équipe choisit des groupes plus petits malgré une baisse du chiffre annoncé. Le succès dépend ici de la relation rendue possible, et non de la seule capacité à remplir la salle. Les médiateurs pourront désormais adapter le parcours et laisser davantage de temps aux questions. La direction suivra les retours des visiteurs pour vérifier que le changement ne favorise pas seulement les personnes déjà familières des musées. Elle souhaite conserver une ouverture large, même avec moins de passages simultanés. Le choix n'oppose donc pas mécaniquement quantité et qualité : il cherche une organisation qui permette de mieux accueillir les publics visés, avec les moyens réellement disponibles.","question":"Quel arbitrage l'équipe assume-t-elle pour rendre la visite plus utile ?","options":["Garder le même nombre d'entrées en répartissant les visiteurs sur davantage de séances","Consacrer davantage de temps aux échanges en réduisant l'accès des visiteurs novices","Accepter une fréquentation annoncée plus faible afin d'améliorer l'accompagnement","Maintenir la durée des visites en supprimant les échanges jugés secondaires"],"correct":"C","explanation":"C. Le texte présente l'acceptation de groupes plus petits, donc d'un chiffre d'entrées moindre, afin de mieux dialoguer et adapter les parcours. A conserverait le volume, B exclurait les visiteurs novices contrairement à l'intention, et D supprimerait les échanges que la salle veut privilégier."}]}$paper$::jsonb);
