 if (select count(*) from academy_tcf_reading.papers where version='tcf-reading-2026-11-advanced-v5' and id in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06'))<>6 then raise exception 'Expected six v5 rows'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06') and version='tcf-reading-2026-11-advanced-v5')<>6 then raise exception 'Six published pointers not all updated'; end if;
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Published reading catalog changed'; end if;
